window.EVENTS_G=[{"id":"G-001","branch":"G","stage":1,"day":1,"shichen":"辰时","checkpoint":"冷灶","scene":"晨起，灶房无火。张家主母说柴米紧，让你添妆里的炭。你立在穿堂，看她把你陪嫁的铜炭箕端去给小叔温酒。两年了，这灶，从不曾为你热过。","options":[{"text":"不去添炭，只把空箕收回房。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"冷灶是他们的，暖不了你的手，也冻不垮你的算计。先护住自己的物，再谈别的。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"乖乖添了炭，讨张家主母欢心。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"张家主母笑你懂事。可炭烧完，冷灶还是冷灶，你连自己的箕都没留住。","source":"同上。"}],"difficulty":1,"npc":["张家主母"],"foreshadow":"嫁资单子"},{"id":"G-001-未","branch":"G","stage":1,"day":1,"shichen":"未时","checkpoint":"截妆","scene":"午后清点箱笼，少了一对银钏。阿瓷低声说，昨儿张家主母说「借去」给姑奶奶添箱。你摸着空了的锦匣——这「借」，从没还过。","options":[{"text":"在单子上添朱批「借而不还，记为侵」。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"字小，可你心里那本账，从此清楚了。记一笔，便少一分被糊弄。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"忍了，想着家丑不外扬。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"忍一次，便有十次，箱笼只会越来越空。忍字头上一把刀。","source":"同上。"}],"difficulty":1,"npc":["阿瓷","张家主母"],"foreshadow":"嫁资单子"},{"id":"G-001-戌","branch":"G","stage":1,"day":1,"shichen":"戌时","checkpoint":"灯下","scene":"夜里点灯，你翻出娘家陪嫁的账底。两年，嫁资去了三成。你对着灯苗出神：这婚是娘家铺的路，如今路断了，人还得自己走。","options":[{"text":"把账底压在枕下，先看清走了多少。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"不是认命，是记路——先看清走了多少，才知还剩多少可走。","source":"同上。"},{"text":"对着灯掉泪，怪自己命不好。","correct":false,"tags":["感情"],"dims":{},"feedback":"泪干了，嫁资不会自己回来。哀怨填不满箱笼。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-002","branch":"G","stage":1,"day":2,"shichen":"辰时","checkpoint":"当书","scene":"张成翻你书架，抽去一函《柳体碑帖》，说「借去赏玩」。你知他从不临帖。阿瓷后来回：他押给了东街当铺，换了十千文。","options":[{"text":"记下当票字号与当铺名。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"书是你的，押也是你的帐，总有一日要赎，或要算。先留痕。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"想着两家一场，便由他去。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"他押的不是书，是你娘家的心意。心软一次，便输一城。","source":"同上。"}],"difficulty":1,"npc":["张成"],"foreshadow":"碑帖"},{"id":"G-002-未","branch":"G","stage":1,"day":2,"shichen":"未时","checkpoint":"市井","scene":"你遣阿瓷去东街探当铺。回来报：碑帖压在柜台里，朝奉说张官人每月付息。汴京的秋，风里都是算计的味道。","options":[{"text":"让阿瓷记住朝奉模样与铺规。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"市井里讨生活，眼要比心先亮。摸清门道，日后才好周旋。","source":"同上。"},{"text":"只叹气，未让阿瓷细问。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"信息差一寸，往后便要吃一丈的亏。叹气填不饱算盘。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"碑帖"},{"id":"G-002-戌","branch":"G","stage":1,"day":2,"shichen":"戌时","checkpoint":"旧信","scene":"翻箱底，摸到二哥旧年捎来的信。他说「娘家永远有你一口饭」。你攥着信角，久未落泪的人，喉头忽然一紧。","options":[{"text":"把信收进贴身小囊。","correct":true,"tags":["家世","自主"],"dims":{"自主":1,"家世":1},"feedback":"娘家是可依的退路，但路要自己迈，不靠哭求。信在身，心便有底。","source":"宋代宗族互助，见《宋史·礼志》。"},{"text":"光顾着伤心，信搁回原处。","correct":false,"tags":["感情"],"dims":{},"feedback":"退路在，不等于你走了。伤心若误事，便是自弃。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-003","branch":"G","stage":1,"day":3,"shichen":"辰时","checkpoint":"冷茶","scene":"晨起，张家主母递来一碗冷茶，说未过门的娘子要知勤俭。你端着碗，看她转手把你陪嫁的漆盒装了她的针线。","options":[{"text":"把漆盒要回，说「这是娘给的」。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一句话，划清了你的与他们的。界清了，往后才好守。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"怕落口舌，没开口。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"盒留了，界也模糊了。怕人言，便总在让。","source":"同上。"}],"difficulty":1,"npc":["张家主母"],"foreshadow":"嫁资单子"},{"id":"G-003-未","branch":"G","stage":1,"day":3,"shichen":"未时","checkpoint":"绣活","scene":"午后张家主母让你绣十方帕子「贴补家用」。你手底功夫好，可这「家用」，从不包括你。","options":[{"text":"绣了，却记着针线是你自己的。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"手是本事，留得本事，便留得底气。市井里，手艺就是饭。","source":"宋代妇人女红自营，见《东京梦华录》。"},{"text":"敷衍了事，帕子被退。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"本事是自己的，糟蹋了可惜。敷衍误的，终是自己。","source":"同上。"}],"difficulty":1,"npc":["张家主母"],"foreshadow":null},{"id":"G-003-戌","branch":"G","stage":1,"day":3,"shichen":"戌时","checkpoint":"独白","scene":"夜深，你对着窗外的汴河水想：这两年，我把自己活成了一张忍字。可忍字头上一把刀，刀不落别人，落的是自己。不如，替自己争一回。","options":[{"text":"对自己说：路是自己走窄的，也能自己走宽。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这一念，便是转身的开始。念想落地，路才现形。","source":"同上。"},{"text":"把「争」字写在单子背面。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"不与人对骂，只与命算账。一笔朱痕，压住一腔委屈。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子","flavor":true},{"id":"G-004","branch":"G","stage":1,"day":4,"shichen":"辰时","checkpoint":"数钱","scene":"张成月钱又短了你二贯，说「生意周转」。你看着他新制的绸衫，知这周转，转不到你身上。","options":[{"text":"当面记了账。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"钱的事含糊不得，含糊一次，便糊涂一世。账立住，话才硬。","source":"嫁资与夫家有别，见司马光《书仪》。"},{"text":"体贴他「不易」，没计较。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"体贴若换不来回头，便是纵他。心软是漏钱的窟窿。","source":"同上。"}],"difficulty":1,"npc":["张成"],"foreshadow":"嫁资单子"},{"id":"G-004-未","branch":"G","stage":1,"day":4,"shichen":"未时","checkpoint":"邻里","scene":"隔壁王娘子来串门，悄说「张家这头，委屈了你」。你笑而不答，心里却记下：这街坊眼里，是有杆的秤。","options":[{"text":"回赠半包茶，落个和气。","correct":true,"tags":["名声","自主"],"dims":{"自主":1,"名声":1},"feedback":"市井里，人缘是暗处的路。留一线，日后好借力。","source":"宋代里坊舆论，见《东京梦华录》。"},{"text":"冷了脸，把人推出门。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"孤则易欺，何必自断臂助。拒人千里，便是自围高墙。","source":"同上。"}],"difficulty":1,"npc":["邻里"],"foreshadow":null},{"id":"G-004-戌","branch":"G","stage":1,"day":4,"shichen":"戌时","checkpoint":"对账","scene":"夜里你铺开嫁资单子，就着灯一笔笔核。两年，少的不止是物，是那点「许了人便有人撑」的念想。","options":[{"text":"重写单子，分「在册」「已失」两栏。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"看清失去的，才护得住还在的。账清了，心便定了。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"盯着单子发呆，不作勾画。","correct":false,"tags":["感情"],"dims":{},"feedback":"账不理，便永远是一团乱。发呆解不了穷。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-005","branch":"G","stage":1,"day":5,"shichen":"辰时","checkpoint":"婆嘴","scene":"张家主母念叨：「女人家，许了人便随人。」你低头应着，手却把单子往袖里收了收——鸡若是豺，随的便是命。","options":[{"text":"应得巧，动得稳。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"嘴上不争，心里不糊涂，这才是市井活法。软钉子最管用。","source":"同上。"},{"text":"与他辩，反落个「不贤」。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"势不如人时，硬碰是傻。辩赢了理，先输了境。","source":"同上。"}],"difficulty":2,"npc":["张家主母"],"foreshadow":"嫁资单子"},{"id":"G-005-未","branch":"G","stage":1,"day":5,"shichen":"未时","checkpoint":"书摊","scene":"你托阿瓷去大相国寺书摊打听碑帖行情。回说那函柳体，识货人出到二十千。张成押的，才十千。","options":[{"text":"记下行情，心里有数。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"物值几何，你心里有数，往后谈判便不慌。懂行才不被欺。","source":"同上。"},{"text":"觉得都是自家的，不必算。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"由他低价押，亏的终是你。一笔糊涂账，养一双贪心手。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"碑帖"},{"id":"G-005-戌","branch":"G","stage":1,"day":5,"shichen":"戌时","checkpoint":"夜算","scene":"灯下你算：嫁资现值、已失、可追，三项列清。算到最后，你忽然笑了——原来自己并非无路，是迟迟没肯算。","options":[{"text":"把三项数字圈了红。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"路在算清处，不在叹息里。红圈一圈，底气一分。","source":"同上。"},{"text":"算了又搁，终无决断。","correct":false,"tags":["感情"],"dims":{},"feedback":"账算清，人不动，也是白搭。犹豫是时间的贼。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-006","branch":"G","stage":1,"day":6,"shichen":"辰时","checkpoint":"截绢","scene":"你陪嫁的葱绿绢两匹，被张家主母截去给张家妹子裁春衣。张家妹子笑盈盈来谢，你却知这「谢」，从不是还。","options":[{"text":"当面说「绢记在单上，日后要算」。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"软中带硬，护的是界。一句话，立住你的账。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"笑着让了，落个大方。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"大方一次，便被当常例。名声换不来绢。","source":"同上。"}],"difficulty":2,"npc":["张家主母","张家妹子"],"foreshadow":"嫁资单子"},{"id":"G-006-未","branch":"G","stage":1,"day":6,"shichen":"未时","checkpoint":"张算","scene":"张成夜归，难得温言问你「可还缺什么」。你知他这是算前先哄——下一件要动的，怕是你那方田庄的契。","options":[{"text":"回得乖，契却藏得更深。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他算他的，你防你的，不露破绽。温柔里藏着刀，你得睁眼。","source":"田产为嫁资，见司马光《书仪》。"},{"text":"因他一句温言便软了心。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"温柔若带钩，最易松手。一句好话，换不走你的契。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":null},{"id":"G-006-戌","branch":"G","stage":1,"day":6,"shichen":"戌时","checkpoint":"藏契","scene":"你趁夜把田庄契与单子缝进夹袄内衬。针脚细密。这衣，往后睡觉也不离身。","options":[{"text":"缝得稳，贴身收着。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"物在手，心才安；契在身，路才不断。针线里缝的是退路。","source":"同上。"},{"text":"犹豫缝不缝，怕伤「两家情分」。","correct":false,"tags":["感情"],"dims":{},"feedback":"情分若靠契保，本就薄。犹豫一夜，险增一分。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-007","branch":"G","stage":1,"day":7,"shichen":"辰时","checkpoint":"冷饭","scene":"早饭又是一碗稀粥。张家主母说「将就」。你端着碗，想起娘家灶上的白米饭——将就的，从来只有你。","options":[{"text":"默默吃完，另留半贯钱嘱阿瓷买干粮。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"将就嘴，不将就骨。自己顾得住自己，才谈得上别的。","source":"同上。"},{"text":"赌气不吃，饿的是自己。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"硬气要有，饭也要吃饱。饿坏了身，谁替你走这条路。","source":"同上。"}],"difficulty":2,"npc":["张家主母"],"foreshadow":null},{"id":"G-007-未","branch":"G","stage":1,"day":7,"shichen":"未时","checkpoint":"阿瓷","scene":"阿瓷悄悄说，她包袱里替你攒了些碎银与旧衣，「娘家的心意，我替你看着」。你鼻头一酸。","options":[{"text":"收下，记在单子。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"有人替你守，更要自己立。情义与算计，本可并行。","source":"婢随女出嫁，见司马光《书仪》。"},{"text":"推说「使不得」，推掉了臂助。","correct":false,"tags":["感情"],"dims":{},"feedback":"苦日子里，情义是粮。推掉的好意，未必再来。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-007-戌","branch":"G","stage":1,"day":7,"shichen":"戌时","checkpoint":"独白","scene":"窗外的更鼓敲过三遍。你摸着夹袄里的契，忽然明白：这两年我守的不是夫家，是自己的退路。退路既在，何不堂堂走？","options":[{"text":"对自己说：我不是逃，是归。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"归到我自己的日子里去。念一转，脊梁便直了。","source":"同上。"},{"text":"把「退路」二字添进单子眉批。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"退是为了进，不是怯。一笔眉批，压住满心惶然。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子","flavor":true},{"id":"G-008","branch":"G","stage":1,"day":8,"shichen":"辰时","checkpoint":"碑帖事","scene":"张成醉酒吹嘘：把那函碑帖「送了上司周监税，换了个好缺」。你指尖一凉——那不是赏玩，是拿你的陪嫁换他的前程。","options":[{"text":"记下碑帖去向、人名、时日。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这是压垮骆驼的，最后一根草。记下来，便是凭据。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"替他遮掩，怪他「也是为家」。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"为家若卖你，这家的秤早斜了。遮掩换不来回头。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":"碑帖"},{"id":"G-008-未","branch":"G","stage":1,"day":8,"shichen":"未时","checkpoint":"压垮","scene":"你独坐房中，把碑帖一事在心里过了三遍。两年冷遇，都不如此刻剜心——他把你最珍的重，随手送了人。","options":[{"text":"提笔在单子末页写：「此恨记，不报，只离。」","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"离，是清醒，不是怨。落笔那一刻，你拿回了主心骨。","source":"同上。"},{"text":"只是哭，哭完照旧过。","correct":false,"tags":["感情"],"dims":{},"feedback":"心碎若不留痕，便碎得无声无息。泪干了，账还在空。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-008-戌","branch":"G","stage":1,"day":8,"shichen":"戌时","checkpoint":"不眠","scene":"这一夜你没睡。就着灯，把嫁资单子从头誊清一遍，添了碑帖一项，朱批「待追索」。天亮时，手稳了。","options":[{"text":"誊得一字不漏。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"把委屈落成字，便不再是委屈，是凭据。手稳了，路就稳。","source":"同上。"},{"text":"困极而眠，单子摊着。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"情绪过了，账却没立。摊着的单子，挡不住明日的手。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-009","branch":"G","stage":1,"day":9,"shichen":"辰时","checkpoint":"探口","scene":"你状似无意问张家主母：「若我想回娘家住些时，可使得？」张家主母眼一锐：「定了亲的女，哪有说走就走。」","options":[{"text":"笑应了，心里却记：这扇门，他们守得紧。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"更要另寻法子。试探得了底，便知从哪处破。","source":"宋代妇人有归宗之例，见司马光《书仪》。"},{"text":"被一句噎住，再不敢提。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"试探不成便缩，探便白探。退一步，门更紧一分。","source":"同上。"}],"difficulty":2,"npc":["张家主母"],"foreshadow":null},{"id":"G-009-未","branch":"G","stage":1,"day":9,"shichen":"未时","checkpoint":"张防","scene":"张成似察觉你异样，软言要「替你保管箱钥」。你知钥匙一交，嫁资便再难清。","options":[{"text":"推说「钥匙串乱，改日理好再交」。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"缓兵也是兵，钥匙攥紧。一句话，护住整箱凭据。","source":"嫁资为妇人之私财，见《名公书判清明集》。"},{"text":"怕生隙，交了钥匙。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"交出去的，往往回不来。怕生隙，先失了底。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":"嫁资单子"},{"id":"G-009-戌","branch":"G","stage":1,"day":9,"shichen":"戌时","checkpoint":"思归","scene":"夜深你想：不如归去——可「归」字何其重。娘家容得，族叔的嘴容不得；街坊的眼，也容不得。","options":[{"text":"想清：归不归，先问法，再问人。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"有理，便不怕嘴。法是盾，先举起来，再谈归途。","source":"宋代妇人有归宗之例，见司马光《书仪》。"},{"text":"怕人言，不敢想归。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"人言可畏，却吓不退该走的路。怕字当头，路便没了。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":null},{"id":"G-010","branch":"G","stage":1,"day":10,"shichen":"辰时","checkpoint":"说书","scene":"街口说书人拍案：「前朝李娘子，才动京华，与夫君同好金石，兵火里把一部《金石录》守了下来，终是活成了自己。」你听得忘了搅粥。","options":[{"text":"记下这故事。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"原来前头有人走过，且走得通。胆，便壮了。借古人之灯，照自己的路。","source":"李清照与赵明诚同好金石，见《金石录后序》。"},{"text":"觉得「那是才女，我不是」。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"故事是灯，你却闭了眼。自矮一截，便先输一阵。","source":"同上。"}],"difficulty":2,"npc":["说书人"],"foreshadow":"李娘子的金石录"},{"id":"G-010-未","branch":"G","stage":1,"day":10,"shichen":"未时","checkpoint":"邻议","scene":"王娘子凑来：「李娘子那事，街坊都说她有本事。」你笑：「本事是表，心里有数才是里。」王娘子怔了怔。","options":[{"text":"借邻人之口，把「女子有学非耻」种进市井。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"舆论，亦可借力。先松了土，日后才好移栽。","source":"宋代女子习学之风，见《东京梦华录》。"},{"text":"附和「女子无才便是德」，把自己也堵了路。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"嘴上的墙，堵的是自己。一句迎合，先缚住脚。","source":"同上。"}],"difficulty":2,"npc":["邻里"],"foreshadow":null},{"id":"G-010-戌","branch":"G","stage":1,"day":10,"shichen":"戌时","checkpoint":"灯悟","scene":"灯下你重写单子扉页：「李娘子能自立，我为何不能自立？」笔尖一顿，竟觉前路初开。","options":[{"text":"落了「自立」二字。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"敢想，路才现；敢写，念才坚。一字落纸，万难减半。","source":"宋女自立有例，见《金石录后序》。"},{"text":"写了又涂，终究没留字。","correct":false,"tags":["感情"],"dims":{},"feedback":"念想不落纸，便易散。涂掉的不是字，是勇气。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-011","branch":"G","stage":1,"day":11,"shichen":"辰时","checkpoint":"族叔","scene":"族叔来访，言谈间劝你「忍字为高，休生事端」。你垂首，知这「体面」，压的是你的活路。","options":[{"text":"应得恭敬，心里却划清。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"体面是他的，活路是你的。面子上过，里子上守。","source":"同上。"},{"text":"被「族中体面」压得不敢动。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"体面若吃人，不要也罢。被一句话捆住，是自己的怯。","source":"同上。"}],"difficulty":2,"npc":["族叔"],"foreshadow":null},{"id":"G-011-未","branch":"G","stage":1,"day":11,"shichen":"未时","checkpoint":"备信","scene":"你暗暗起意：该给二哥捎个信了。阿瓷问「写什么」，你说「只说天凉，问安」。","options":[{"text":"写得隐，心意却明。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"家书是暗线，不宜直，宜稳。一字藏锋，便护住一线生机。","source":"宋代家书往来，见《宋史·礼志》。"},{"text":"迟迟不写，怕添二哥烦忧。","correct":false,"tags":["感情"],"dims":{},"feedback":"可沉默，才是真添忧。该张口时闭口，误的是自己。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"娘家信"},{"id":"G-011-戌","branch":"G","stage":1,"day":11,"shichen":"戌时","checkpoint":"独白","scene":"更鼓声里，你抚着单子想：这两年我学的最狠一课，是——别人靠不住时，自己便是靠山。退亲不是末路，是归途。","options":[{"text":"对自己说：靠山山倒，靠人人走，靠自己立得稳。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"三字抵万语。自己站稳了，风便吹不倒你。","source":"同上。"},{"text":"把「靠自己」写在单子角。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"三字，抵得过千句旁人劝。落纸为凭，夜半不慌。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子","flavor":true},{"id":"G-012","branch":"G","stage":1,"day":12,"shichen":"辰时","checkpoint":"交信","scene":"你嘱阿瓷：「这信，你亲自送回娘家，交二哥手，莫经他人。」阿瓷把信掖进包袱最里层。","options":[{"text":"交得稳，经一人之手。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"要事经一人之手，便少一分走漏。线头攥紧，棋才不乱。","source":"同上。"},{"text":"图省事托旁人带。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"信落错手，事便生变。省的一步，往往最贵。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-012-未","branch":"G","stage":1,"day":12,"shichen":"未时","checkpoint":"张疑","scene":"张成见阿瓷出门，盘问「去哪」。你淡答「买针线」，挡在阿瓷前。他哼了声，没再深究。","options":[{"text":"挡得自然，护住臂助。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"护住臂助，便是护住退路的线头。一句话，挡开一双眼。","source":"同上。"},{"text":"如实说「回娘家」，断了暗线。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"坦白的时机，不在此时。一句实话，废了全盘计。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":"阿瓷的包袱"},{"id":"G-012-戌","branch":"G","stage":1,"day":12,"shichen":"戌时","checkpoint":"待讯","scene":"夜来你望着窗外，等阿瓷的消息。两年冷灶，今夜竟有一丝暖——是「要动手了」的暖。","options":[{"text":"沉住气，静待回音。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"大事将启，最忌慌。静，是另一种力。稳住心神，棋才落得准。","source":"同上。"},{"text":"坐立不安，往复踱到天明。","correct":false,"tags":["感情"],"dims":{},"feedback":"心乱，则棋乱。一夜焦灼，耗的是自己的神。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"娘家信"},{"id":"G-013","branch":"G","stage":2,"day":13,"shichen":"辰时","checkpoint":"二哥至","scene":"三日后二哥竟亲自来了，风尘仆仆。他握你手：「信收到了。咱慢慢来，依礼走路，不慌。」","options":[{"text":"点头，把事交兄长定计。","correct":true,"tags":["家世","自主"],"dims":{"自主":1,"家世":1},"feedback":"有兄撑腰，依礼而行，最是正途。靠山到了，步子才敢迈。","source":"宋代宗族相助之义，见《宋史·礼志》。"},{"text":"只顾哭，话未听进。","correct":false,"tags":["感情"],"dims":{},"feedback":"亲人在侧，更要清醒听计。泪淹了耳，便漏了策。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"娘家信"},{"id":"G-013-未","branch":"G","stage":2,"day":13,"shichen":"未时","checkpoint":"查律","scene":"二哥摊开抄来的司马光《书仪》：「嫁资本是女之私财，夫家不得擅用。」你指尖点着那行，久旱逢雨。","options":[{"text":"逐字记下礼文。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"礼文是你的盾，先读熟，才用得准。字字入心，临阵不慌。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"只觉解气，未细读。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"盾在手中不会用，等于无。解气换不来赢面。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"嫁资单子"},{"id":"G-013-戌","branch":"G","stage":2,"day":13,"shichen":"戌时","checkpoint":"兄妹计","scene":"灯下兄妹定计：先清嫁资、再依古礼与旧约自保，最后行退亲。二哥说：「一步一据，他们挑不出错。」","options":[{"text":"把三步写在单子背面。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"依礼走，步步是钉，钉死退路。有章法，便不怕反扑。","source":"古礼重信约，见司马光《书仪》。"},{"text":"只盼快些了事，不顾步骤。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"急则生错，错则授柄。图快一步，反慢一程。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"嫁资单子"},{"id":"G-014","branch":"G","stage":2,"day":14,"shichen":"辰时","checkpoint":"解约","scene":"二哥留下的抄本写：「旧约虽定，若一方失信，约可解。」你对着镜子，把「解约」二字念出口，竟不颤了。","options":[{"text":"念得稳，先把名分立在口。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"词不练，临阵必卡。先在嘴里磨利，事到临头才不慌。","source":"旧约可解，见司马光《书仪》。"},{"text":"觉得「说出来不吉利」，憋在心里。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"名分不立，便先矮半截。吉利躲不过该来的难。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":null},{"id":"G-014-未","branch":"G","stage":2,"day":14,"shichen":"未时","checkpoint":"古礼","scene":"抄本又载：「受聘在前、无家可归」者，旧约不当轻废。你正合「无家可归」这一条。","options":[{"text":"圈住这条，护住自己。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"他们想赖这旧约，先过这一条。手里有这条，腰便直。","source":"古礼护弱，见司马光《书仪》。"},{"text":"怕他们不认这条，慌了神。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"律在纸上，亦在你手。慌了，便是把刀递出去。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":null},{"id":"G-014-戌","branch":"G","stage":2,"day":14,"shichen":"戌时","checkpoint":"独白","scene":"二哥走后，你对着单子笑：原来我并非孤身一人，亦非无法无天。法在，兄在，路就在。这两年冷灶，烧到最后竟暖了手。","options":[{"text":"对自己说：暖手的不靠灶，靠的是自己与点亮的人。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"冷过的人，才知一点暖金贵。这暖，是你自己挣来的。","source":"同上。"},{"text":"记下「兄妹同心」四字。","correct":true,"tags":["家世"],"dims":{"家世":1},"feedback":"身后有人，步子才敢迈大。四字落纸，底气又添一分。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"嫁资单子","flavor":true},{"id":"G-015","branch":"G","stage":2,"day":15,"shichen":"辰时","checkpoint":"索帖","scene":"你借二哥支招，遣人去周监税处询那函碑帖。回话：周大人嫌俗，搁在库房。你知，追索有隙。","options":[{"text":"记下库房位置与经手人。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"物要回，先摸清它在哪。线索在手，追索才有门。","source":"嫁资为妇人之私财，见《名公书判清明集》。"},{"text":"觉得「算了，不要也罢」。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"不要，便是白送他前程。你珍的重，凭什么不要。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"退亲书"},{"id":"G-015-未","branch":"G","stage":2,"day":15,"shichen":"未时","checkpoint":"拟书","scene":"二哥帮你拟退亲底稿，你执笔润色：句句引礼，字字留据。阿瓷在旁研墨，眼里有了光。","options":[{"text":"润得准，句句有凭。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"文书是脸面，也是刀刃，须利而正。字字着力，才立得住。","source":"宋代退亲文书，见乡里旧例。"},{"text":"嫌麻烦，草草抄完。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"文书潦草，便授人以柄。麻烦省一时，祸患留长久。","source":"同上。"}],"difficulty":2,"npc":["二哥","阿瓷"],"foreshadow":"退亲书"},{"id":"G-015-戌","branch":"G","stage":2,"day":15,"shichen":"戌时","checkpoint":"退亲","scene":"灯下你读乡里退亲旧例：「旧约既释，各奔前程。」八个字，把你两年的硬，化成了柔。","options":[{"text":"把八字抄在单尾。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"退亲不是恨，是给彼此松绑。八字落纸，心也松了。","source":"乡里退亲旧例：「旧约既释，各奔前程。」"},{"text":"嫌这词太淡，想写满怨。","correct":false,"tags":["感情"],"dims":{},"feedback":"怨写多了，便困住了自己。淡不是薄，是放过。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"退亲书"},{"id":"G-016","branch":"G","stage":2,"day":16,"shichen":"辰时","checkpoint":"呈单","scene":"你将誊清的嫁资单子呈二哥过目。他叹：「条理清楚，便是半张状子。」你知，这一仗，赢在准备。","options":[{"text":"听进夸，更补了缺漏。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"准备越细，变数越小。半张状子，要磨成整张的赢。","source":"同上。"},{"text":"得意，搁了笔不再核。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"满足即是松懈的开始。得意忘形，最易漏疮。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"嫁资单子"},{"id":"G-016-未","branch":"G","stage":2,"day":16,"shichen":"未时","checkpoint":"张觉","scene":"张成似风闻你动静，软中带硬：「这事好聚好散，别闹到官前。」你笑：「既不闹，便依礼书一封。」","options":[{"text":"以「礼」应「软」，反将一军。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他怕官，你正好用官外的礼逼他。一句话，把主动权夺回。","source":"宋代退亲重书契，见司马光《书仪》。"},{"text":"被「好聚好散」哄软，不立字。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"口说无凭，日后翻脸难。软话里藏的是空。","source":"同上。"}],"difficulty":3,"npc":["张成"],"foreshadow":"退亲书"},{"id":"G-016-戌","branch":"G","stage":2,"day":16,"shichen":"戌时","checkpoint":"婆拦","scene":"张家主母闻风来拦：「退了，你往哪搁？族里脸面呢？」你平静答：「脸面在理，不在压人。」","options":[{"text":"答得平，以理破情。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"以静制动，她噪不得。理字当头，脸面便压不住你。","source":"同上。"},{"text":"被「脸面」说得心虚，退了半步。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"半步一退，便难收。心虚一次，气势先衰。","source":"同上。"}],"difficulty":3,"npc":["张家主母"],"foreshadow":null},{"id":"G-017","branch":"G","stage":2,"day":17,"shichen":"辰时","checkpoint":"族议","scene":"族叔被请来「主持公道」。他板脸：「女子无端退亲，不成体统。」你捧出单子与礼文，请他「依礼说话」。","options":[{"text":"以礼请礼，堵了他的嘴。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"体统若悖律，便只是私心。亮出凭据，他无从发作。","source":"同上。"},{"text":"怯于族威，不敢出示凭据。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"有凭不示，等于无凭。怕一字，输一局。","source":"同上。"}],"difficulty":3,"npc":["族叔"],"foreshadow":"嫁资单子"},{"id":"G-017-未","branch":"G","stage":2,"day":17,"shichen":"未时","checkpoint":"叔劝","scene":"族叔私下劝二哥：「让你妹忍忍，张家到底门第不差。」二哥看你，你摇头：「门第再好，不是我的活路。」","options":[{"text":"摇头摇得定。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"门第是别人的，活路是自己的。一句话，断了旁人拿捏的念。","source":"同上。"},{"text":"因「门第」二字动摇。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"门第压人时，便不值钱。一动摇，前功便松。","source":"同上。"}],"difficulty":3,"npc":["族叔","二哥"],"foreshadow":null},{"id":"G-017-戌","branch":"G","stage":2,"day":17,"shichen":"戌时","checkpoint":"碑归","scene":"你托二哥周旋，将那函碑帖从周监税库房讨回。捧在手里，墨香犹在。两年，它终于回家。","options":[{"text":"把碑帖供回书架。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"物归原主，亦是气归原主。失而复得，最知珍重。","source":"嫁资追索，见司马光《书仪》。"},{"text":"讨回却闷着，不与人说。","correct":false,"tags":["感情"],"dims":{},"feedback":"喜事不说，便少了份底气。闷在心里，福也减三分。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"碑帖"},{"id":"G-018","branch":"G","stage":2,"day":18,"shichen":"辰时","checkpoint":"书契","scene":"二哥请了乡绅作见证，草拟退亲书。你逐句念：「嫁资随女，各无干涉。」张成迟迟不肯落笔。","options":[{"text":"盯着他笔，寸步不让。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"落笔前，寸步不让；落笔后，干干净净。这一笔，写的是自由。","source":"退亲文书格式，见乡里旧例。"},{"text":"心软，说「少写两句也行」。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"让一步，便可能让掉嫁资。软一次，悔一世。","source":"同上。"}],"difficulty":3,"npc":["二哥","张成"],"foreshadow":"退亲书"},{"id":"G-018-未","branch":"G","stage":2,"day":18,"shichen":"未时","checkpoint":"张让","scene":"张成见势不妙，愿「让你带走嫁资，只求不声张」。你平静：「正合我意。白纸黑字，免得夜长梦多。」","options":[{"text":"收得稳，立下细据。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他要静，你要据；据到手，静便是你的。字据才是真金。","source":"同上。"},{"text":"为「不声张」暗喜，未立细据。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"不立据的便宜，最易翻。一时的脸面，换长久的悬心。","source":"同上。"}],"difficulty":3,"npc":["张成"],"foreshadow":"嫁资单子"},{"id":"G-018-戌","branch":"G","stage":2,"day":18,"shichen":"戌时","checkpoint":"独白","scene":"碑帖归架那夜，你沏了盏茶，对自己说：这两年我像被雨淋透的纸，如今晾干了，能重新写字。退亲不是输，是重写。","options":[{"text":"对自己说：纸干了，笔在我手，写什么由我。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"主动权回到了自己手里。这一盏茶，敬的是重生的你。","source":"同上。"},{"text":"把「重写」二字记在单上。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"放下错的，才接得住对的。重写二字，是给未来的请柬。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"退亲书","flavor":true},{"id":"G-019","branch":"G","stage":2,"day":19,"shichen":"辰时","checkpoint":"立据","scene":"退亲书终于誊正：嫁资逐项列清，碑帖、田契、绢帛俱在。你与张成各执一笔，落下姓名。","options":[{"text":"落笔不抖，旧账两清。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"名字一画，新路初开。手稳，是因为理直。","source":"宋代退亲需立书，见司马光《书仪》。"},{"text":"落笔时手颤泪落，乱了墨。","correct":false,"tags":["感情"],"dims":{},"feedback":"大事当前，心先稳住。泪乱了墨，也乱了阵。","source":"同上。"}],"difficulty":3,"npc":["二哥","张成"],"foreshadow":"退亲书"},{"id":"G-019-未","branch":"G","stage":2,"day":19,"shichen":"未时","checkpoint":"辞张","scene":"你最后一次走张家门。张家主母别过脸，张家妹子不送。你只把单子折好，对阿瓷说：「走，回娘家。」","options":[{"text":"走得稳，不回头。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"门里是旧冷，门外是娘家灯。转身干脆，便是给自己体面。","source":"宋代妇人离夫归宗，见《宋史·礼志》。"},{"text":"回头望了一眼，乱了心神。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"既走，望即是缠。一回头，便少一分决绝。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-019-戌","branch":"G","stage":2,"day":19,"shichen":"戌时","checkpoint":"娘灯","scene":"夜归娘家，二哥在灯下候你。你捧出单子与退亲书：「都清了。」灯花爆了一下，像替你贺。","options":[{"text":"把凭据交二哥收着。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"事了，凭在，人才安。灯下这一刻的暖，是清白换来的。","source":"同上。"},{"text":"只哭诉委屈，凭据搁一边。","correct":false,"tags":["感情"],"dims":{},"feedback":"泪可流，凭不可忘。哭过了，凭据才是真的靠。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"娘家信"},{"id":"G-020","branch":"G","stage":2,"day":20,"shichen":"辰时","checkpoint":"新晨","scene":"晨起，你亲自生了火，煮了自己的一碗白粥。阿瓷笑：「娘子如今，灶是自己的了。」你尝一口，暖到心底。","options":[{"text":"生火生得安然。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"自己的灶，煮自己的饭，这一步，走得值。暖从手心起。","source":"同上。"},{"text":"等着二哥来安排，自己不动手。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"靠人惯了，便忘了手热。灶在眼前，也要自己生。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-020-未","branch":"G","stage":2,"day":20,"shichen":"未时","checkpoint":"前路","scene":"二哥问你往后打算。你说：「先理嫁资、再慢慢挑人——这一回，我要自己点头。」窗外的汴京，秋光正好。","options":[{"text":"说得清，自己掌舵。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"良缘的前提，是先做回自己的人。这一回，你说了算。","source":"宋代妇人出嫁自主，见《宋史·范仲淹传》。"},{"text":"说「听兄长安排」，交还舵。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"舵在别人手，风便不由你。才出的笼，别又进框。","source":"同上。"}],"difficulty":2,"npc":["二哥"],"foreshadow":"退亲书"},{"id":"G-020-戌","branch":"G","stage":2,"day":20,"shichen":"戌时","checkpoint":"独白","scene":"退亲后第一夜，你拥被而坐，想：前朝李娘子走通的路，我也走通了。往后的良缘，不在命里，在我自己手里。","options":[{"text":"对自己说：路是自己走通的，良缘也该自己接住。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这一步，你替自己走成了。后面的好，才配得上清醒的你。","source":"李清照自立其身，见《金石录后序》。"},{"text":"把「良缘可期」写在单子末。","correct":true,"tags":["情缘"],"dims":{"情缘":1},"feedback":"清过旧账，才装得下新欢喜。这一笔，是给未来的预约。","source":"宋代出嫁为常，见《宋史·范仲淹传》。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"嫁资单子","flavor":true},{"id":"G-021","branch":"G","stage":2,"day":21,"shichen":"辰时","checkpoint":"族叔施压","scene":"辰光斜进堂屋，族叔端坐，捋须叹气：「张家的脸面，经不得你这一闹。女子从一而终，退亲传出去，族中如何抬头？」你垂眸，袖中那卷《书仪》微微发烫。","options":[{"text":"取出司马光《书仪》退亲之条，从容念出：两愿退亲，各还聘财，各听另许。你一字一顿，念得极稳。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你一字一句念出礼文，族叔一时语塞。懂礼不是男人的专利，你拿得住自己的路。","source":"同上。"},{"text":"低头认错，说都是自己一时闹脾气。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你一软，族叔便得了势，反说你「不懂事」。退一步，未必换得体面。","source":"同上。"}],"difficulty":2,"npc":["族叔"],"foreshadow":null},{"id":"G-021-未","branch":"G","stage":2,"day":21,"shichen":"未时","checkpoint":"张家主母劝留","scene":"张家主母端了碗银耳羹过来，坐你身旁，语气软了三分：「成哥儿性子慢，不是坏心。你回去，往后事由我替你压着。女子离开张家，外头的话多难听。」你接碗，指尖凉。","options":[{"text":"温声谢过张家主母好意，却说路已定了，不回头。","correct":true,"tags":["自主"],"dims":{"自主":1,"名声":1},"feedback":"你谢她，却不改主意。软话最易化人骨，你接得住，也放得下。","source":"宋代户婚之法，见《宋史·刑法志》。"},{"text":"被说动，犹豫要不要再等等。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"一等便是一退。退亲是你想清了两年的事，不该因一碗羹软下来。","source":"同上。"}],"difficulty":2,"npc":["张家主母"],"foreshadow":null},{"id":"G-021-戌","branch":"G","stage":2,"day":21,"shichen":"戌时","checkpoint":"备底单","scene":"戌时的灯下，阿瓷替你展开那卷娘家装箱的底单，又取出官中备下的嫁资官档。她小声说：「姑娘，单子对得上，张家扣不得。」你将纸张一一抚平，压在镇纸下。","options":[{"text":"将底单与官档并排收好，逐项核对无误。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"早备下的底单，是你给自己留的后路。嫁资清白，张家无从扣起。","source":"嫁资官档之制，见《名公书判清明集》。"},{"text":"觉得都是自家人，单子放娘家就行。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"自家人三字最误事。单子不握在手里，便等于没备。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"嫁资单子"},{"id":"G-022","branch":"G","stage":2,"day":22,"shichen":"辰时","checkpoint":"长老施压","scene":"族叔这回带了族中长老的意思来，话里话外是「女子无才便是德，闹退亲毁门风」。他压低声：「忍忍，便过去了。」","options":[{"text":"说礼文是护人的，不是比高低，退亲于礼皆允。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你没被「毁门风」三个字拿住。法度在前，闲话在后，你站得稳。","source":"宋代退亲之制，见《宋史·礼志》及宋人笔记。"},{"text":"解释自己不是针对族中男人。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你越解释，越像心虚。门风二字压不住懂礼的人。","source":"同上。"}],"difficulty":2,"npc":["族叔"],"foreshadow":null},{"id":"G-022-未","branch":"G","stage":2,"day":22,"shichen":"未时","checkpoint":"呈单作证","scene":"你当着族叔的面，将娘家装箱的底单与官档一并取出，逐条念出嫁资名目。你说：「叔父请看，哪些是张家的，哪些是我的，白纸黑字。」他翻了翻，神色松了些。","options":[{"text":"以底单官档为凭，言明嫁资交割有据。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"纸面清楚，族叔挑不出错。有据可依，比哭求管用百倍。","source":"嫁资官档之制，见《名公书判清明集》。"},{"text":"只口头说嫁资都是你的，拿不出单子。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"口说无凭，张家便有空子可钻。单子才是硬道理。","source":"同上。"}],"difficulty":2,"npc":["族叔"],"foreshadow":"嫁资单子"},{"id":"G-022-戌","branch":"G","stage":2,"day":22,"shichen":"戌时","checkpoint":"二哥来信","scene":"戌时灯暖，阿瓷递来二哥的家书。他字少：「妹既有决断，兄不拦。嫁资若生波，我自来作证。」你捏着信纸，窗外风过，心里却定了。","options":[{"text":"回信说「有兄这句话，我安心了」，落笔从容。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"二哥的沉默支持，是你底气的一半。你不孤单，路是自己走，也有人托底。","source":"宋代宗族相助，见家训。"},{"text":"将信收进嫁资匣，与底单一处。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"把支持落到实处，纸信与单子同匣，往后要用时，一样拿得出手。","source":"同上。"}],"difficulty":1,"npc":["二哥","阿瓷"],"foreshadow":"阿瓷的包袱","flavor":true},{"id":"G-023","branch":"G","stage":2,"day":23,"shichen":"辰时","checkpoint":"张成图产","scene":"张成踱到你房外，语气不冷不热：「你那嫁资，这几年也算是张家养你的本。要走，总该留些做补偿。」你听了，指尖发凉。","options":[{"text":"拿出底单，说嫁资各有名目，岂能混作张家养你的本。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他图的是含糊，你给的是清楚。名目分明，念想二字挤不进来。","source":"嫁资为妇人之私财，见《名公书判清明集》。"},{"text":"心软，说留一两件也无妨。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"一退便退不完。留一件，他便要十件。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":null},{"id":"G-023-未","branch":"G","stage":2,"day":23,"shichen":"未时","checkpoint":"张家主母扣产","scene":"张家主母忽地翻了脸，说陪嫁那匣金钏该留张家。她拍着柜子：「进了这门，便是张家的物。」你看着那匣，想起底单上明写「妻奁，不系夫产」。","options":[{"text":"引礼文，言女之嫁资不在夫家财产，金钏当归你。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"你一句「不系夫产」，张家主母哑了。礼文是你最稳的靠山。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"退让，说金钏留给张家主母戴着玩。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"退一件，张家便当你好说话。嫁资要整箱整匣地走。","source":"同上。"}],"difficulty":2,"npc":["张家主母"],"foreshadow":null},{"id":"G-023-戌","branch":"G","stage":2,"day":23,"shichen":"戌时","checkpoint":"装箱封条","scene":"戌时，你与阿瓷将可动产一一装箱，封了纸条。阿瓷把你的贴身包袱也理好，小声道：「姑娘，能带走的，咱都带走。」烛火跳着，箱面映出你平静的脸。","options":[{"text":"逐箱封条编号，与底单对锁，一件不落。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"装箱封条是给自己的交代。带走该带的，从此两清。","source":"嫁资随嫁之俗，见宋代笔记与《名公书判清明集》。"},{"text":"嫌沉，挑几样不紧要的留下。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"不紧要也会被人说成「自愿留」。封条要封全。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-024","branch":"G","stage":2,"day":24,"shichen":"辰时","checkpoint":"措辞之争","scene":"双方坐定谈退亲书措辞，族叔提笔要写「女不贤，约当解」。你搁茶盏：「解与逐不同。两愿乃退亲，措辞须实。」堂上静了一息，张成垂眼不语。","options":[{"text":"坚持「两愿退亲」，不认「女不贤」。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你守住的是名，也是往后说亲的底气。一字不让，步步为营。","source":"退亲文书措辞，见乡里旧例。"},{"text":"忍了，说写什么都行，快些了事。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"「都行」二字最蚀人。白纸黑字跟着你后半生。","source":"同上。"}],"difficulty":2,"npc":["族叔","张成"],"foreshadow":null},{"id":"G-024-未","branch":"G","stage":2,"day":24,"shichen":"未时","checkpoint":"敦煌格式","scene":"你取出抄录的乡里退亲旧例，说：「前人行事，愿文平和——『旧约既释，各奔前程』。咱们照这般写，不伤体面。」张成抬眼，似没想到你会备这一手。","options":[{"text":"主张依乡里退亲旧例，平和了断，各奔前程。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"「旧约既释」是你给这段旧约最后的体面，也给你自己。","source":"乡里退亲旧例。"},{"text":"由着张家写，只求快签。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"由人落笔，体面便在他人手里。格式也要自己定。","source":"同上。"}],"difficulty":2,"npc":["张成","族叔"],"foreshadow":"退亲书"},{"id":"G-024-戌","branch":"G","stage":2,"day":24,"shichen":"戌时","checkpoint":"张成松动","scene":"谈至戌时，张成忽然松口：「既如此，便依你，体面收场。」他补一句：「嫁资照单还，人……各自安生。」你点点头，没多说一句话，把这一句落进心里。","options":[{"text":"颔首应下，言「各奔前程」，不纠缠旧账。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"他松口，你也不趁机翻旧。路走通即可，不必踩到底。","source":"同上，乡里退亲旧例。"},{"text":"追问他一句「你可曾悔过」。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"追问悔过，是把未了的线又扯紧。你已向前，不必回头。","source":"同上。"}],"difficulty":1,"npc":["张成"],"foreshadow":"退亲书"},{"id":"G-025","branch":"G","stage":2,"day":25,"shichen":"辰时","checkpoint":"赖箱风波","scene":"交割前清点，张成家说后院那一箱缂丝早用坏了，不在数内。你翻开底单，那箱明写着「完好随嫁」。你抬眼：「单上有名，便该原样还。」","options":[{"text":"持底单对质，言箱物完好，须照单交割。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"一句「单上有名」，赖不掉。底单就是你的剑，出鞘便见血。","source":"嫁资交割有据，见《名公书判清明集》。"},{"text":"说少一箱也无妨，算了。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"算了一次，张家便当你好欺。单上的每箱都要回来。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":null},{"id":"G-025-未","branch":"G","stage":2,"day":25,"shichen":"未时","checkpoint":"二哥作证","scene":"二哥遣来的老仆到了，捧着娘家留底的装箱录。他当众说：「这录上每件都盖过娘家印，可做证。」族叔点头：「既有两边底单，便没话了。」你眼底微热。","options":[{"text":"谢过二哥派来的人，将娘家录并入交割。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"两边底单并齐，张家再无空子。家人的证，是底气也是暖。","source":"娘家备录作证，见宋代嫁资之俗。"},{"text":"推说不必惊动二哥，自己能行。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"能行也要有证。二哥的录，是你多一层保险。","source":"同上。"}],"difficulty":2,"npc":["二哥","族叔"],"foreshadow":"嫁资单子"},{"id":"G-025-戌","branch":"G","stage":2,"day":25,"shichen":"戌时","checkpoint":"斟酌愿文","scene":"戌时的灯下，你重写退亲书草稿，逐字斟酌那句愿文。写到「旧约既释，各奔前程」，你顿笔——这两年凉薄，到底也到此为止。墨迹干透，像替自己松了绑。","options":[{"text":"定下愿文，留「旧约既释，各奔前程」八字。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"愿文是你亲手定的体面。绑着的是过往，松的是往后。","source":"乡里退亲旧例。"},{"text":"改写得冷硬，要显决绝。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"冷硬不是强，是余气未消。「各奔前程」四字，才是真放下。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"退亲书"},{"id":"G-026","branch":"G","stage":2,"day":26,"shichen":"辰时","checkpoint":"族叔点头","scene":"族叔最后来看你，叹了口气：「你比张家那些男人，倒更懂礼度。」他竟没再拦。你福了一礼：「叔父成全，侄女记着这份体面。」他摆手，转身时背略弯了。","options":[{"text":"从容谢过族叔，言路是自己走通，也谢他最后的成全。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"他不拦，你也不骄。体面是互相给的，你接住了。","source":"宗亲调处之俗，见宋代族规与笔记。"},{"text":"得意，说早说过张家留不住你。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"得意便折了体面。路通了，不必踩他人一头。","source":"同上。"}],"difficulty":2,"npc":["族叔"],"foreshadow":"退亲书"},{"id":"G-026-未","branch":"G","stage":2,"day":26,"shichen":"未时","checkpoint":"定稿画押","scene":"退亲书定稿，墨香未散。你与张成各自执笔，要在骑缝处画押。落笔前，他忽看你一眼，你垂眸，笔尖稳稳按下——这一押，两年便结清了。","options":[{"text":"提笔从容画押，字字清楚，不颤不悔。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"押是结清，不是认输。你这笔，写得比谁都稳。","source":"宋代退亲之制，见司马光《书仪》及宋人笔记。"},{"text":"手抖，迟迟落不下笔。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"抖的是余情，不是路错。既想清了，笔便该稳。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":"退亲书"},{"id":"G-026-戌","branch":"G","stage":2,"day":26,"shichen":"戌时","checkpoint":"夜雨收装","scene":"戌时落了雨，你与阿瓷在灯下收最后几件行装。她把那包袱系紧，轻声说：「姑娘，明日出了这门，便是新的人了。」雨打窗纸，你忽然觉得，这两年像一场醒得迟的梦。","options":[{"text":"抚过行装，说「醒得不迟，此刻正好」。","correct":true,"tags":["自主"],"dims":{"自主":1},"feedback":"你不怨醒得迟。迟来的清醒，也是清醒。包袱里装的是往后。","source":"退亲出行之状，见乡里旧例与宋人笔记。"},{"text":"替阿瓷也理了包袱，说咱们一起走。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"你没把她落下。主仆同行，是冷世里一点暖，也是你的体面。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱","flavor":true},{"id":"G-027","branch":"G","stage":3,"day":27,"shichen":"辰时","checkpoint":"交割嫁资","scene":"签书当日，嫁资一箱箱点数交清。张成家的管事逐箱验过，你持底单勾销，件件对上。最后一只箱合上时，你听见自己轻轻吐了口气——两年的牵扯，到此物归原主。","options":[{"text":"依底单逐箱勾销，嫁资整整齐齐交割完毕。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"勾销最后一笔，物归原主。你带走该带的，不欠不拖。","source":"嫁资交割，见《名公书判清明集》。"},{"text":"嫌烦，让管事自己点，你不过目。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"不过目便可能短少。交割要亲眼，才叫清。","source":"同上。"}],"difficulty":2,"npc":["张成","管事"],"foreshadow":"退亲书"},{"id":"G-027-未","branch":"G","stage":3,"day":27,"shichen":"未时","checkpoint":"退亲落笔","scene":"未时正，退亲书铺在案上，乡里格式的愿文居中。你与张成各执一笔，在「旧约既释，各奔前程」下写名。笔落纸响，像替这段旧约，轻轻合上一本书。","options":[{"text":"端端正正落名，念一句「各奔前程」，神色安宁。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"名落愿文，旧约便正式结清。「各奔前程」四字，你给得真心。","source":"乡里退亲旧例。"},{"text":"迟迟不落名，想再拖一日。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"拖一日，便多捆一日。书该合了，别留指缝。","source":"同上。"}],"difficulty":2,"npc":["张成"],"foreshadow":"退亲书"},{"id":"G-027-戌","branch":"G","stage":3,"day":27,"shichen":"戌时","checkpoint":"出门那步","scene":"戌时的风凉，你提着裙摆，走到张府那道门槛前。两年里你无数次跨进跨出，这一回，是带着自己的嫁资、自己的名，跨出去。脚落在外头青石上，你没回头。","options":[{"text":"稳稳迈出门槛，嫁资随行，一步未停。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"这一步，你跨的是自己的命。没回头，是因为前头有路。","source":"出离之仪，见宋人笔记与乡里旧例。"},{"text":"到门槛又顿住，想再看一眼旧屋。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"再看一眼，心便软一截。该走就走，不立在此处。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"退亲书"},{"id":"G-028","branch":"G","stage":3,"day":28,"shichen":"辰时","checkpoint":"归家车马","scene":"归家的车马慢行在汴京巷里，几家邻舍探头探脑。你端坐车中，听见有人说「张家那娘子回来了」。你拢了拢膝上包袱，神色如常——这条路，你选的，不怕人看。","options":[{"text":"端坐如常，任人看，不躲不辩。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你越坦，闲话越落空。归家是你自己的步子，不必藏。","source":"宋人街巷闲观之俗，见《东京梦华录》。"},{"text":"拉帘遮脸，怕人认出。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"遮一次，便要遮一世。你没做亏心事，何须藏。","source":"同上。"}],"difficulty":1,"npc":["邻舍"],"foreshadow":null},{"id":"G-028-未","branch":"G","stage":3,"day":28,"shichen":"未时","checkpoint":"娘的泪","scene":"进门时娘迎上来，眼圈红红，一把攥住你的手：「我的儿，受苦了。」你反握娘的手，笑说：「娘，我好好回来了，往后咱娘俩安稳过。」她泪落，却点了头。","options":[{"text":"反慰娘，说路是自己走的，如今踏实了。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"你没倒在娘泪里。反慰一句，是给娘也是给自己底气。","source":"母女之情，见宋人家训与笔记。"},{"text":"跟着娘哭，说这两年好难。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"哭一场无妨，但若只哭，便还困在旧里。你先稳，娘才安。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":null},{"id":"G-028-戌","branch":"G","stage":3,"day":28,"shichen":"戌时","checkpoint":"二哥斟酒","scene":"戌时，二哥在院里摆了小桌，默默斟了一杯酒推给你，只说三字：「回来了。」没问张家对错，没说门风。你接杯，酒微苦，落肚却暖——有些支持，原不必多言。","options":[{"text":"接杯饮下，回「嗯，回来了」，与二哥对坐。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"二哥的三字，是全家最重的托底。你接住，便不孤单。","source":"兄弟相扶，见宋代家训。"},{"text":"推说不会喝，怕二哥多想。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"一杯酒是亲近，推了便远了。自家兄长，不必设防。","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":null},{"id":"G-029","branch":"G","stage":3,"day":29,"shichen":"辰时","checkpoint":"闲言顶住","scene":"邻家妇人隔着墙根嘀咕：「退过亲了，怕是有什么不妥。」你听见，手上理衣的动作没停，隔墙回一句：「人好好站着呢，不妥的是闲话，不是我。」那边忽地静了。","options":[{"text":"平静接住闲话，不怒不辩，只点破「不妥的是嘴」。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你一句顶回去，不羞不恼。闲话最怕不怕它的人。","source":"市井闲议之态，见《东京梦华录》。"},{"text":"关窗躲，当没听见。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"躲一次，闲话便当你心虚。你站得住，就让它落空。","source":"同上。"}],"difficulty":2,"npc":["邻妇"],"foreshadow":null},{"id":"G-029-未","branch":"G","stage":3,"day":29,"shichen":"未时","checkpoint":"李娘子暗线","scene":"又有长舌说：「前朝那李娘子，抛头露面校书，多难看。」你停了针线，抬眼：「她敢在天地间立住自己，我也敢。难看的是绑人，不是她。」那人讪讪走了。","options":[{"text":"敬李清照之敢，言「她敢，我也敢」，不消费不轻慢。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你把李娘子当镜，不当谈资。敬其敢，是你自己的骨气。","source":"李清照校书立名事，见《金石录后序》。"},{"text":"附和说李娘子确实不体面。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"附和闲话，便成了帮腔。你该敬的，是同样的敢。","source":"同上。"}],"difficulty":2,"npc":["邻妇"],"foreshadow":"碑帖"},{"id":"G-029-戌","branch":"G","stage":3,"day":29,"shichen":"戌时","checkpoint":"夜抄启文","scene":"戌时灯下，你铺纸抄李清照《金石录后序》中自陈之句。笔尖过处，你想她亦曾在兵火里护书，不为媚人，只为不负。抄完，你轻轻吹干墨，像与千年前的她，隔纸一揖。","options":[{"text":"工整抄录后序，敬其护书之勇，不消费其苦。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"你抄的是骨气，不是八卦。敬一个人，是把她的勇，活成自己的。","source":"李清照《金石录后序》。"},{"text":"只摘艳词抄，当风雅消遣。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"只摘艳词，便轻了她的重。敬，要敬到骨头里。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"碑帖"},{"id":"G-030","branch":"G","stage":3,"day":30,"shichen":"辰时","checkpoint":"晨起空落","scene":"早起竟无人来唤你梳洗，屋里静得生疏。你坐在床沿，有一瞬空落——两年晨昏都有人安排，如今全要自己来。你愣了愣，起身，给自己倒了杯温茶。","options":[{"text":"承认这空落，却也起身自理，一杯温茶先暖自己。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"空落是真，缓过来也是真。你先照自己，路便接着走。","source":"离后独居之实感，见宋人笔记。"},{"text":"慌了，想回张家图个有人管。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"慌的是不习惯，不是走错。有人管，是旧的捆。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":null},{"id":"G-030-未","branch":"G","stage":3,"day":30,"shichen":"未时","checkpoint":"重理书案","scene":"你打开随嫁的书匣，翻出旧日抄的金石笔记。纸角有些卷，字迹却还在。你抚平一页，想起未嫁时也曾伏案摹拓。指尖停了停，竟比前几日，多了点沉静。","options":[{"text":"重理金石笔记，把旧好拾起来，慢慢来。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"旧好还在，你便没丢自己。沉静，是从书案上一点一点回来的。","source":"宋女习书摹拓之俗，见《金石录》及笔记。"},{"text":"觉得这些没用，搁回箱底。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"嫌没用，是忘了这是你。笔记是你的根，别埋了。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"金石笔记"},{"id":"G-030-戌","branch":"G","stage":3,"day":30,"shichen":"戌时","checkpoint":"夜对娘坐","scene":"戌时，娘端了羹来，见你灯下临帖，竟笑了：「我儿还是小时候那个性子。」你抬眼，娘的笑里没了泪。两人对坐半晌，没说什么要紧话，屋里却比前几日暖了。","options":[{"text":"与娘对坐，听她笑，自己也松了眉。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"娘的笑，是家给你的回音。你稳了，家也跟着暖回来。","source":"母女相守，见宋人笔记。"},{"text":"留着那页临帖，说往后常写给娘看。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"你把旧好变成与娘的伴。路通了，连亲情都找回了样子。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":"金石笔记","flavor":true},{"id":"G-031","branch":"G","stage":3,"day":31,"shichen":"辰时","checkpoint":"赁院看房","scene":"你带阿瓷上街看小院，中介领着转了几处。你专挑近书肆、有南窗的。站在一处小院里，光打在青砖上，你想：往后这方天地，是自己的名下的了。","options":[{"text":"定下近书肆、有南窗的小院，自赁自立。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"赁下小院，是立住的 first step。名下的屋，装得下你的往后。","source":"汴京赁屋之俗，见《东京梦华录》。"},{"text":"图便宜租了偏远潮暗的一间。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"便宜换委屈。南窗与书肆近，才是你要的。","source":"同上。"}],"difficulty":2,"npc":["阿瓷","中介"],"foreshadow":null},{"id":"G-031-未","branch":"G","stage":3,"day":31,"shichen":"未时","checkpoint":"包袱搬物","scene":"阿瓷随你搬物，她背上那个包袱始终不撒手。你笑问装的什么，她说是你最珍爱的几卷碑帖，「姑娘离张家没带别的，就带了这个，我敢不护着？」你鼻头一酸，又笑了。","options":[{"text":"谢阿瓷护着碑帖，说这才是最要紧的物。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"碑帖是你的魂，阿瓷懂。紧要的物有人懂，是幸。","source":"碑帖随嫁之俗，见宋人笔记。"},{"text":"说旧帖不值钱，让她轻些搁。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你不认它的重，便轻了自己的根。值不值，你心里最清楚。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-031-戌","branch":"G","stage":3,"day":31,"shichen":"戌时","checkpoint":"赎回碑帖","scene":"戌时你翻出当票——去年急用，将一卷心爱碑帖当了。你换了钱，循着当铺去赎。掌柜递还时笑：「娘子倒是念旧。」你接过，指尖摩挲那拓痕，像接回一小片自己。","options":[{"text":"如期赎回碑帖，物归原处，不教它流落。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"赎回的岂止一纸拓。是你没丢的自己，回来了。","source":"宋时质库（当铺）之制，见《东京梦华录》。"},{"text":"觉得赎不起，算了让它去。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"赎不起便算了，便是又丢一片自己。咬咬牙，接回来。","source":"同上。"}],"difficulty":2,"npc":["掌柜"],"foreshadow":"碑帖"},{"id":"G-032","branch":"G","stage":3,"day":32,"shichen":"辰时","checkpoint":"小院安顿","scene":"小院安顿好，你把随身书画一一挂起。南窗下那幅旧临《峄山碑》，映着晨光，竟比在张家库房里精神。你退后两步看，忽然觉得，这屋子开始像「你的」了。","options":[{"text":"亲手挂起书画，把南窗下布置成书案。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"挂画是安家，也是安心。屋子像你了，你便立住了。","source":"宋人书斋布置，见《东京梦华录》及笔记。"},{"text":"随便堆着，说住住再说。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"随便堆，屋子便还是客居。你要把它变成「我的」。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"金石笔记"},{"id":"G-032-未","branch":"G","stage":3,"day":32,"shichen":"未时","checkpoint":"娘家尾款","scene":"二哥遣人送来娘家补的嫁资尾款，附话：「妹既自立，这点贴补你收着，赁屋用度不愁。」你点数，正好补上赎帖的缺口。你笑：二哥的沉默，原都落在实处。","options":[{"text":"收下尾款，记清账目，自立不靠赖，也不推拒亲情。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"收得坦，记得清。自立不是孤，是该接的暖也接住。","source":"娘家补贴之俗，见宋代嫁资笔记。"},{"text":"硬拒，说绝不花娘家一文。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"硬拒是赌气。二哥给的是托底，不是施舍。","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":"阿瓷的包袱"},{"id":"G-032-戌","branch":"G","stage":3,"day":32,"shichen":"戌时","checkpoint":"重拾临摹","scene":"戌时你重铺纸，执笔临摹那卷赎回的碑帖。手起初微颤，到第三行竟稳了。墨痕一笔笔落下，你听见自己呼吸平了——这两年荒掉的，正一点一点，回到指尖。","options":[{"text":"日日临摹，手渐稳，把荒掉的好重新练回。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"手稳了，心也稳。你找回的，是一个会执笔的自己。","source":"摹拓习字，见《金石录》及宋人笔记。"},{"text":"临两笔嫌累便搁了。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"搁下容易拾起难。稳，是天天临出来的。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"碑帖"},{"id":"G-033","branch":"G","stage":3,"day":33,"shichen":"辰时","checkpoint":"闲言渐消","scene":"过了些时日，邻里见你每日自在进出、临帖会友，那「残了」的闲话竟少了。卖花的婆子还探头问你讨临的帖子。你笑递一张，风评这东西，原是你自己写给人看的。","options":[{"text":"以自在立身，闲言自消，还结了善缘。","correct":true,"tags":["名声","自主"],"dims":{"自主":1,"名声":1},"feedback":"你活得好，闲话便站不住。名声是自己挣回的。","source":"市井观人，见《东京梦华录》。"},{"text":"特意打扮招摇，要人看。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"招摇是求看，反而轻。自在，才最重。","source":"同上。"}],"difficulty":1,"npc":["邻舍","卖花婆"],"foreshadow":null},{"id":"G-033-未","branch":"G","stage":3,"day":33,"shichen":"未时","checkpoint":"书画换脩","scene":"有邻家学子来求你临帖，愿奉束脩。你应下，定下规矩：按月交帖，银钱清清楚楚。第一笔束脩入匣时，你想：自食其力，原来是从一笔一画里来的。","options":[{"text":"以书画授徒换束脩，银钱立账，自食其力。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"束脩入匣，是你自己挣的。立住，从这一笔一画始。","source":"宋时女教与束脩之俗，见笔记。"},{"text":"不好意思收钱，白教。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"白教是轻己。清账收钱，才叫立身。","source":"同上。"}],"difficulty":2,"npc":["学子"],"foreshadow":"金石笔记"},{"id":"G-033-戌","branch":"G","stage":3,"day":33,"shichen":"戌时","checkpoint":"夜读法度","scene":"戌时你重翻司马光《书仪》旧卷，就着灯一行行读。从前为自保才翻它，如今读来，竟觉礼度原是护人的——不只护你，也护天下如你这般，想站直的人。","options":[{"text":"静读礼文，知礼度护人，自立更有底。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你从怕礼到懂礼，再到借礼立身。路通，是因为你读得透。","source":"宋代户婚之礼，见《宋史·礼志》。"},{"text":"觉得读过便够，不必再翻。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"礼文要常读常新。懂礼不是一劳，是随身。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"退亲书"},{"id":"G-034","branch":"G","stage":3,"day":34,"shichen":"辰时","checkpoint":"拟立赁约","scene":"你请人拟赁约，一字字看得分明：租期、租金、修缮谁担，都写死。中介笑你仔细，你说：「自己的屋事，含糊不得。」落笔画押那刻，你比签退亲书，更觉踏实。","options":[{"text":"逐项厘清赁约，落笔清楚，护住自己的居所。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"赁约清楚，居所才稳。你连签两次文书，一次退，一次立。","source":"宋代赁屋立契之俗，见《名公书判清明集》。"},{"text":"觉得中介说怎样就怎样。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"含糊的约，日后便是坑。居所要自己护。","source":"同上。"}],"difficulty":2,"npc":["中介"],"foreshadow":null},{"id":"G-034-未","branch":"G","stage":3,"day":34,"shichen":"未时","checkpoint":"旧物归还","scene":"张成遣人送来一物——是你当年忘在厢房的旧砚，附话：「物归原主。」你接下，没多言。阿瓷问要不要回礼，你摇头：「他给的体面，我收下，不纠缠。」","options":[{"text":"安然收下旧砚，不回礼不纠缠，两清。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"收下放得下，不纠缠是最后的体面。两清，便真清了。","source":"退亲后物归，见乡里旧例。"},{"text":"回赠厚礼，怕显得小气。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"回厚礼是没放下。清，就清到底。","source":"同上。"}],"difficulty":1,"npc":["张成","阿瓷"],"foreshadow":"阿瓷的包袱"},{"id":"G-034-戌","branch":"G","stage":3,"day":34,"shichen":"戌时","checkpoint":"夜话打算","scene":"戌时灯下，你与阿瓷说往后打算：赁院、授徒、慢慢把金石小集做成。她托腮笑：「姑娘如今，比在张家时亮堂。」你看着她，忽然觉着，身边有这一个懂你的人，便是福。","options":[{"text":"与阿瓷细说自立打算，眼里有了光。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"打算说出口，路便更真。有阿瓷懂你，冷世里这点暖最贵。","source":"主仆相随之情，见宋人笔记。"},{"text":"记下令阿瓷的那份，说往后不分彼此。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"你没把她当附庸。同行的人，要记在心上、落在实里。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"阿瓷的包袱","flavor":true},{"id":"G-035","branch":"G","stage":3,"day":35,"shichen":"辰时","checkpoint":"书肆论词","scene":"书肆里有人高声谈李清照词，说「寻寻觅觅」凄婉。你驻足，轻声接：「她亦有『生当作人杰』的硬气。」旁人看向你，你坦然：敬她，是敬那股不肯弯的劲。","options":[{"text":"于书肆论李词之硬气，敬其不肯弯。","correct":true,"tags":["才华","名声"],"dims":{"自主":1,"才华":1},"feedback":"你读词读到了骨。敬李娘子，是把她的硬，活成自己的脊。","source":"李清照词，见《漱玉词》及宋人评。"},{"text":"只附和说词真凄美。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"只说凄美，便轻了她的硬。你该读出那股劲。","source":"同上。"}],"difficulty":2,"npc":["书肆众人"],"foreshadow":"拓片"},{"id":"G-035-未","branch":"G","stage":3,"day":35,"shichen":"未时","checkpoint":"写跋明志","scene":"归来你展纸写一小跋，论「女子亦能立学全名，非耻也」。落墨时你想：李娘子走过的水深，你不过浅涉，却已懂——敢立住，名节自在。","options":[{"text":"写跋明志，言女子立学亦能全名，非耻。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"跋是你给自己的判词。全名不在守，而在敢立。","source":"女子立学全名，见李清照《金石录后序》。"},{"text":"写些伤春悲秋，掩住真意。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"掩真意，便白写。跋要写的，是你的骨。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"金石笔记"},{"id":"G-035-戌","branch":"G","stage":3,"day":35,"shichen":"戌时","checkpoint":"娘劝旧事","scene":"娘来瞧你，劝道：「往后再出嫁也好，独过也罢，莫在人前提退亲旧事，惹闲话。」你温声应：「娘放心，我不消费自己的难，也不藏。该说时说，是敬那段路。」","options":[{"text":"温应娘，言不消费旧难，也不藏，坦荡处之。","correct":true,"tags":["自主","感情"],"dims":{"自主":1,"名声":1},"feedback":"你不让旧事成谈资，也不当羞处。坦荡，是给娘最好的安。","source":"宋人处旧之智，见笔记。"},{"text":"全听娘的，从此绝口不提。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"绝口是藏，藏便还痛。坦荡说，才是真过。","source":"同上。"}],"difficulty":1,"npc":["娘"],"foreshadow":null},{"id":"G-036","branch":"G","stage":3,"day":36,"shichen":"辰时","checkpoint":"回娘理账","scene":"你回娘家一趟，与二哥就着嫁资尾款理清总账。算盘珠子响过，两数对上。二哥难得笑：「妹这账，比我还清。」你收好单子——从底单到尾款，全在自己手里了。","options":[{"text":"与二哥理清总账，嫁资来去皆有据。","correct":true,"tags":["自主","家世"],"dims":{"自主":1,"家世":1},"feedback":"账清，心才清。从底单到尾款，你全攥住了。","source":"嫁资理账之俗，见《名公书判清明集》。"},{"text":"含糊说一句「够用就行」。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"含糊便可能糊涂。账要清，才叫自立。","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":"嫁资单子"},{"id":"G-036-未","branch":"G","stage":3,"day":36,"shichen":"未时","checkpoint":"族叔偶遇","scene":"街口偶遇族叔，他竟难得说句：「张家那头，到底亏了你。」你微微一笑，福礼：「叔父当日成全，侄女记着。」他咳一声，竟也露了点笑意，拱手走了。","options":[{"text":"从容谢过族叔旧日成全，不骄不怨。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"他认张家亏，你认体面。这一笑，是前嫌最轻的句号。","source":"宗亲和解，见宋代族规笔记。"},{"text":"回一句「早说过」。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"早说过是显胜。体面，要留给彼此。","source":"同上。"}],"difficulty":1,"npc":["族叔"],"foreshadow":null},{"id":"G-036-戌","branch":"G","stage":3,"day":36,"shichen":"戌时","checkpoint":"焚稿留清","scene":"戌时你翻出旧年写的一些不合心意的诗稿，多是讨好张成的句子。你一张张理出，投入炉中。火光里，你想：烧掉不是悔，是留一间干净的屋子给往后。","options":[{"text":"焚去旧年讨好的诗稿，留清醒给自己。","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"烧稿是清旧念。往后写的，该只为自己。","source":"焚稿明志，见宋人笔记。"},{"text":"留着，说毕竟是旧物。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"留着便还绊着。清屋子，要从清稿始。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"金石笔记"},{"id":"G-037","branch":"G","stage":4,"day":37,"shichen":"辰时","checkpoint":"嫁资入账","scene":"嫁资清点入账完毕，你对着总单出神：两年委屈，到底换回一身清白与安稳。你提笔在册尾写「自立」二字——从今往后，这名字下的日子，自己写。","options":[{"text":"结清入账，提笔写「自立」，定下往后自己过。","correct":true,"tags":["自主"],"dims":{"自主":2},"feedback":"入账是收尾，自立是开头。你给自己写的二字，最重。","source":"嫁资入账之制，见《名公书判清明集》。"},{"text":"觉得钱够花，懒得再谋事。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"够花是停。你才刚立住，路还长。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":null},{"id":"G-037-未","branch":"G","stage":4,"day":37,"shichen":"未时","checkpoint":"书肆寻帖","scene":"你往相国寺书肆寻碑帖，汴京九月，寺前槐叶铺地。摊上拓片层层，你指尖拂过，停在某一唐碑拓上。掌柜笑：「娘子懂行，这纸旧拓可贵。」你颔首，心里却另有所待。","options":[{"text":"于相国寺书肆细选拓片，眼力清楚，不盲从。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"你认得纸认得拓，也认得自己要什么。书肆，是你的天地。","source":"相国寺书肆，见《东京梦华录》。"},{"text":"听掌柜吹便掏钱。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"盲从便易吃亏。你懂行，该自己断。","source":"同上。"}],"difficulty":2,"npc":["掌柜"],"foreshadow":"拓片"},{"id":"G-037-戌","branch":"G","stage":4,"day":37,"shichen":"戌时","checkpoint":"拓前初遇","scene":"戌时余光里，你正欲伸手取那架上的拓片，另一侧也有手伸来。你抬眼，是个温润男子，见你，微退半步：「娘子请。」你浅笑，自己取了隔壁一幅——这一架前，你们不过初遇。","options":[{"text":"从容取了隔壁拓片，与他对视一礼，克制不逾。","correct":true,"tags":["情缘","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你没慌，也没黏。初遇止于伸手，是分寸，也是你立住后的从容。","source":"宋时书肆雅集，见《东京梦华录》及《金石录》。"},{"text":"与他攀谈起来，问东问西。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"才初遇便热络，便失了分寸。你刚立住，不必急。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":"拓片"},{"id":"G-038","branch":"G","stage":4,"day":38,"shichen":"辰时","checkpoint":"互道姓氏","scene":"翌日书肆，你们竟又遇。这回他先开口：「昨日唐突。在下赵不弃，藏些金石。」你浅福：「免贵，姓……」各执拓片一端，相视而笑——姓氏之间，已无昨日生分。","options":[{"text":"落落报姓氏，与他各执拓片一端，礼数周全。","correct":true,"tags":["情缘","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你报姓不躲，执拓不怯。分寸里的亲近，最见你立得住。","source":"宋人雅士相交，见《金石录》及笔记。"},{"text":"含糊不报姓，转身就走。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"躲是还怕生。既遇，落落报之便是。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":"拓片"},{"id":"G-038-未","branch":"G","stage":4,"day":38,"shichen":"未时","checkpoint":"金石相谈","scene":"他谈起一纸汉碑拓，你竟接得上，说某字剥蚀处当以别本对校。赵不弃眼亮：「娘子亦通此道？」你笑：「略懂，闲来摹着玩。」温润守礼，话到即止，不越半分。","options":[{"text":"以金石之学与他从容对谈，才学相映，话止有度。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你以才学相见，而非以色。这样的近，才配得上你刚立住的身。","source":"金石考校，见赵明诚《金石录》。"},{"text":"故作不懂，让他显能。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"装不懂是媚，失了你自己。你通，便坦坦接着。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":"拓片"},{"id":"G-038-戌","branch":"G","stage":4,"day":38,"shichen":"戌时","checkpoint":"夜归耳热","scene":"戌时归家，阿瓷见你耳尖微红，抿嘴笑：「姑娘今日，倒是鲜活了些。」你摸脸，也笑：「许是书肆风暖。」灯下两人笑作一团——你久违的鲜活，原来不必靠谁给。","options":[{"text":"由阿瓷取笑，坦然觉着自己鲜活起来。","correct":true,"tags":["情缘","自主"],"dims":{"自主":1,"情缘":1},"feedback":"耳热是生春，你却知鲜活在自己心里。立住后，才接得住这点动。","source":"宋人闺中闲趣，见笔记。"},{"text":"记起那架拓片，想明日还去书肆看看。","correct":true,"tags":["情缘","才华"],"dims":{"才华":1,"情缘":1},"feedback":"你想再去，不为缠，为那分寸里的金石缘。路通了，才敢有念。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"拓片","flavor":true},{"id":"G-039","branch":"G","stage":4,"day":39,"shichen":"辰时","checkpoint":"遣童送样","scene":"赵不弃遣小童送来一纸拓样，附字温厚：「前日所谈汉碑，此本稍清，娘子或可用。」你展开，拓痕清晰。小童说：「先生嘱我，莫扰娘子清静。」你微微一笑。","options":[{"text":"安然收下拓样，记着这份温厚守礼。","correct":true,"tags":["情缘","才华"],"dims":{"才华":1,"情缘":1},"feedback":"他送得克制，你收得安然。这样的近，才不惊你刚立的局。","source":"宋人投赠拓本之雅，见《金石录》及笔记。"},{"text":"拒收，怕惹闲话。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"拒是还怕。清白相交，何须躲。","source":"同上。"}],"difficulty":2,"npc":["赵不弃","小童"],"foreshadow":"拓片"},{"id":"G-039-未","branch":"G","stage":4,"day":39,"shichen":"未时","checkpoint":"回帧礼尚","scene":"你取自己临的一帧碑帖回赠，附字：「拙临奉答，不敢言工。」阿瓷问要不要多写几句，你摇头：「礼尚往来，恰恰好便够。」封好，托小童带回——分寸，你守得稳。","options":[{"text":"以临帖回赠，措辞得体，礼止其分。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你回得雅，也回得止。礼尚不来往纠缠，是你立住后的从容。","source":"宋人尺牍往来，见笔记与《金石录》。"},{"text":"回赠厚重，想压过他。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"压人是争。礼尚是平，不是赛。","source":"同上。"}],"difficulty":2,"npc":["阿瓷","小童"],"foreshadow":"拓片"},{"id":"G-039-戌","branch":"G","stage":4,"day":39,"shichen":"戌时","checkpoint":"先立后缘","scene":"戌时你对着拓片出神，想：出嫁与否，且慢些定。先立住的自己，才是往后任何一段缘的底。你抚过纸面，觉着这一回，路怎么走，都由得你。","options":[{"text":"定下「先立己，再论缘」，不慌不迎。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你把次序摆正。立住，才配得上任何将来的好。","source":"宋女自立之念，见笔记与李清照金石之志。"},{"text":"开始盘算何时出嫁。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"才初遇便谋嫁，便轻了刚立的己。慢些。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"拓片"},{"id":"G-040","branch":"G","stage":4,"day":40,"shichen":"辰时","checkpoint":"重订目录","scene":"你重订金石小集目录，把赎回的、新得的拓片一一编入。笔尖沙沙，你想这小集往后只署自己的名。分类、题跋、钤印，皆出自你手——这方天地，清清楚楚是你的。","options":[{"text":"重订金石目录，自署其名，把喜好做成事业。","correct":true,"tags":["才华","自主"],"dims":{"自主":1,"才华":1},"feedback":"目录是你立的旗。往后无论缘来缘往，你先有自己的一摊。","source":"编订金石目录，见赵明诚《金石录》体例。"},{"text":"懒得编，拓片随手堆。","correct":false,"tags":["才华"],"dims":{"才华":1},"feedback":"随手堆便散了。编起来，才是你的业。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"拓片"},{"id":"G-040-未","branch":"G","stage":4,"day":40,"shichen":"未时","checkpoint":"寺中约观","scene":"赵不弃遣字，约你寺中再观新拓。你回「辰刻便往」，不早不晚。阿瓷笑你竟应得爽利，你说：「金石之约，坦坦去，有何不可。」——这一回，你赴的是自己的兴致。","options":[{"text":"爽利应下观拓之约，坦然而往，不躲不缠。","correct":true,"tags":["情缘","自主"],"dims":{"自主":1,"情缘":1},"feedback":"你应得坦，去得爽。赴的是兴致，也是你立住后的自在。","source":"相国寺雅集，见《东京梦华录》。"},{"text":"推三阻四，怕人闲话。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"推是还怯。清白之约，坦坦去便是。","source":"同上。"}],"difficulty":2,"npc":["赵不弃","阿瓷"],"foreshadow":"拓片"},{"id":"G-040-戌","branch":"G","stage":4,"day":40,"shichen":"戌时","checkpoint":"夜抚拓片","scene":"戌时你抚着新编的拓片，灯下回想这二十日：从族叔施压到迈出张府门，从空落到案前临帖，再到书肆那架拓片前的手。你轻轻笑——路，原来早通了，只是你才走到。","options":[{"text":"夜抚拓片，静览来路，知自己已立住、路已通。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"二十日走完最难一段。你立住了，往后金石与缘，皆由你执笔。","source":"自立之路，见全段剧情与《金石录》。"},{"text":"叹还差得远，愁绪又上。","correct":false,"tags":["感情"],"dims":{"名声":1},"feedback":"愁是低估自己。你已走过最难，该信这路。","source":"同上。"}],"difficulty":2,"npc":["阿瓷"],"foreshadow":"拓片"},{"id":"G-041","branch":"G","stage":4,"day":41,"shichen":"辰时","checkpoint":"书肆重逢","scene":"相国寺书肆里，你正翻一册汉碑拓片。有人在你身侧停步，温声问：「娘子也看汉碑？」抬头，竟是那日初遇的赵不弃。他手里也捧着拓片，笑意浅浅。","options":[{"text":"「借光一观。」将拓片递去半幅，与他同看。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你们就着日光共看拓片，他指碑阴款识，你补出缺字。话头，就此开了。","source":"宋代金石之好，见李清照《金石录后序》。"},{"text":"「素不相识，不敢叨扰。」侧身避开。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你退了半步。他也不恼，只颔首让过。书肆人多，这一面险些擦肩。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"金石拓片"},{"id":"G-041-未","branch":"G","stage":4,"day":41,"shichen":"未时","checkpoint":"借稿校勘","scene":"隔日他遣人送来一函，附帖：「闻娘子通文墨，可否以此《金石录》稿本校一校碑目？」展开，竟是李清照辑录的残稿，纸角有旧墨渍。","options":[{"text":"「且试。」铺纸研墨，逐条比勘。","correct":true,"tags":["才华"],"dims":{"才华":1},"feedback":"你校出三条讹误，朱笔小楷写在浮签上。他来取时看了许久，只说「娘子眼力好」。","source":"李清照《金石录后序》自述校书事。"},{"text":"「字太草，看不得。」原样退回。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你原样退回。他接函时微怔，仍道声有劳。门房说，他立在巷口站了一会儿。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"《金石录》稿本"},{"id":"G-041-戌","branch":"G","stage":4,"day":41,"shichen":"戌时","checkpoint":"拓片订交","scene":"暮色里阿瓷抱回一包拓片，说是赵家送的「订交之礼」。展开，是《汉曹全碑》精拓。附笺：「以石上字，结人间交。」你指尖停在「不」字上。","options":[{"text":"「收下，回笺道谢。」提笔写「石不能言最可人」。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你回笺致意，他次日又送来解碑的注本。一来一往，金石成了你们的话头。","source":"宋人以拓片相赠订交，见《金石录后序》。"},{"text":"「退回，今时不兴这个。」连笺一并还去。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你将拓片退回。阿瓷嘀咕「可惜了」，你只说不必。这回交情，你仍攥得紧。","source":"同上。"}],"difficulty":1,"npc":["赵不弃","阿瓷"],"foreshadow":"金石拓片"},{"id":"G-042","branch":"G","stage":4,"day":42,"shichen":"辰时","checkpoint":"雅集同游","scene":"二哥来说，城东文人雅集，赵不弃也在。你本想推，他却道：「去去无妨，都是明处的场合。」你换素衫随他同往，远远见赵不弃在檐下看画。","options":[{"text":"「既来了，便大大方方见。」随二哥上前见礼。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你落落上前见礼。满座都是读书人，谈笑在明处，反倒教你心定了几分。","source":"宋人雅集多在公开场所，见孟元老《东京梦华录》。"},{"text":"「我在此处等，不靠前。」躲到廊后。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你躲在廊后，只听他与人论画，声气温和。二哥来拉你，你摇头。这回你不愿被人看。","source":"同上。"}],"difficulty":1,"npc":["赵不弃","二哥"],"foreshadow":"雅集"},{"id":"G-042-未","branch":"G","stage":4,"day":42,"shichen":"未时","checkpoint":"二哥在座","scene":"茶过三巡，二哥不知怎的，当众问赵不弃：「你可知我家阿妹从前——」你筷子一搁，截了话头。赵不弃只笑笑，替你圆了场。","options":[{"text":"「二哥莫多口，各人过往，自己说才作数。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你轻描淡写截住话头，既护了体面，也叫赵不弃看见：你的事，你自个儿拿主意。","source":"宋人婚议重「自主」，见司马光《书仪》。"},{"text":"（任由二哥说下去）","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"二哥话头没拦住，旁人神色微动。赵不弃却淡然举杯，仿佛没听见。你事后悔了。","source":"同上。"}],"difficulty":1,"npc":["二哥","赵不弃"],"foreshadow":null},{"id":"G-042-戌","branch":"G","stage":4,"day":42,"shichen":"戌时","checkpoint":"夜话·往事前尘","scene":"归家夜话，阿瓷替你拢了灯。你想起白日那句「自己说才作数」，忽觉胸口松了一块。灯花爆了下，像谁替你舒了口气。","options":[{"text":"「我这半生，最怕的，是旁人替我做主。」","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你把旧事轻轻放在灯下。说出来的那一刻，你发现它没那么沉了。这夜话，说给自己听。","source":"李清照同好金石、自立立名，见《金石录后序》。"},{"text":"「可今日，竟有人肯等我自己开口。」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"灯影里你微微弯了嘴角。等一个人自己开口，是这世上顶贵气的体贴。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"灯","flavor":true},{"id":"G-043","branch":"G","stage":4,"day":43,"shichen":"辰时","checkpoint":"碑阴共赏","scene":"又是朔日，书肆里他摊开新得的唐碑拓，指给你看碑阴一行小字：「这字风，像不像你前日校的那条？」你凑近，果真。","options":[{"text":"「像。可见一人书风，隔朝也认得。」","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你们就着碑阴对看半晌，他说「知音难遇」，你没接话，却记下了。","source":"宋人辨碑重书风，见《金石录后序》。"},{"text":"「看不出，许是凑巧。」挪开眼。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你挪开眼。他也不强说，只将拓片卷好。有些亲近，你仍本能地往后缩。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"碑拓"},{"id":"G-043-未","branch":"G","stage":4,"day":43,"shichen":"未时","checkpoint":"退书初回","scene":"阿瓷抱回他新送的书，你忽然慌了：一来二去，这算什么？你叫阿瓷：「原样退回去，说我近日不看书。」阿瓷应声，又迟疑。","options":[{"text":"「退吧。我心里还没安稳，不能误人。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"书退了。你立在窗前想了许久——你不是嫌他，是怕自己又信错了人。","source":"宋女许嫁多审慎，见《书仪》。"},{"text":"「……还是留下吧。」又收下了。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你终是留下了。可夜里翻来覆去，怕的仍是旧事重演。退与留，你都还没想清。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"门房的书"},{"id":"G-043-戌","branch":"G","stage":4,"day":43,"shichen":"戌时","checkpoint":"朔望之约","scene":"两日后门房递进一笺：「知娘子审慎，不敢相逼。此后每月朔望，送一册书到门房，看与不看，都在你。」你捏着笺，半天没言语。","options":[{"text":"「……既不逼我，便由他。」将笺收进匣中。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你没回话，却把笺收好。每月朔望，门房果然多一册书。你先是不取，后来看了。","source":"宋人婚前有「纳采」「问名」之礼，重循序渐进，见《书仪》。"},{"text":"「烧了，省得碍眼。」将笺投入灯里。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你将笺烧了。可第二月初一，门房还是递来一册书。他没问你要不要，只默默送。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"门房的书"},{"id":"G-044","branch":"G","stage":4,"day":44,"shichen":"辰时","checkpoint":"门房取书","scene":"这月朔日，你终是遣阿瓷去门房取了那册书。翻开，是他朱批过的《金石录》校本，边角写着「此条待娘子正」。","options":[{"text":"「他倒会激将。」提笔在待正处补了注。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你补了注，心里那点坚冰，悄悄裂了道缝。原来被人认真对待，是这样的。","source":"李清照与明诚「相对展玩咀嚼」，见《金石录后序》。"},{"text":"「与我无干。」合上不碰。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你合上书。可那行「待娘子正」总在眼前晃。你不是不想，是不敢认自己想要。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"门房的书"},{"id":"G-044-未","branch":"G","stage":4,"day":44,"shichen":"未时","checkpoint":"邻里闲言","scene":"巷口几个妇人凑着你家小院嘀咕：「听说那赵家公子常送书？一个退过亲的娘子，也敢这样招摇。」风把话送进窗棂。","options":[{"text":"「过我的日子，轮不着旁人编排。」自顾理花。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你没出门理论，只把花理得更齐整。闲言是旁人的嘴，你的日子是你的手。","source":"宋代户婚之礼，见《宋史·礼志》。"},{"text":"「她们是不是在说我？」慌得关了院门。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你慌忙关了门。闲言没停，反在背后更响了。你越怕，越显得心虚。","source":"同上。"}],"difficulty":2,"npc":["邻里"],"foreshadow":null},{"id":"G-044-戌","branch":"G","stage":4,"day":44,"shichen":"戌时","checkpoint":"灯下自问","scene":"灯下你问阿瓷：「你说，我这回，是不是又犯傻？」阿瓷摇头：「娘子只是怕。怕，不是傻。」你怔了怔，把针线放下了。","options":[{"text":"「怕就怕着，书且看着。」重新翻开那册校本。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你重新翻开书。怕与想，原可以并存。这一夜，你第一次没把「出嫁」当成别人的事。","source":"宋女自立议亲，见《书仪》及当时风俗。"},{"text":"「不看了，眼烦。」将书塞进柜底。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你把书塞进柜底。可那行待正的字，还在柜里等你。你只是暂时，不愿面对自己。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":null},{"id":"G-045","branch":"G","stage":4,"day":45,"shichen":"辰时","checkpoint":"拓本相质","scene":"书肆里他拿来一方残碑拓，有字漫漶：「这处我吃不准，想请娘子一观。」你接过，指了指石花下的笔意。","options":[{"text":"「是『永』字缺笔，避讳所致。」断得干脆。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你一语道破。他抚掌：「果然。」两人相视一笑，都在明处的光里。","source":"宋人校碑重避讳，见《金石录后序》。"},{"text":"「我哪看得准，你自便。」推回去。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你推了回去。他也不恼，自去琢磨。你错过了一回与他并肩的机会。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"碑拓"},{"id":"G-045-未","branch":"G","stage":4,"day":45,"shichen":"未时","checkpoint":"闲言再起","scene":"闲话又起：「前头张家那桩还沸反盈天，这赵家公子莫不是不知情？」你听见，手里茶盏一顿，随即放下。","options":[{"text":"「我的过往，与旁人何干。喝我的茶。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你淡然继续喝茶。闲言像风过檐角，你不当回事，它自己就散了。","source":"市井闲议之态，见《东京梦华录》。"},{"text":"「她们定是故意气我。」摔了茶盏。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"茶盏碎了，闲言却更盛。你越动气，越落了下风。体面，是稳出来的。","source":"同上。"}],"difficulty":2,"npc":["邻里"],"foreshadow":null},{"id":"G-045-戌","branch":"G","stage":4,"day":45,"shichen":"戌时","checkpoint":"退书二次","scene":"你又慌了，叫阿瓷：「这回的书，退了吧。我怕——」阿瓷捧着书，半天：「娘子，你退的是书，还是他？」你一时答不上。","options":[{"text":"「……先退。等我问清自个儿的心。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"书又退了。可你夜里反复想阿瓷那句：你退的，到底是书，还是那点想被人好的念头？","source":"宋女自立议亲，见《书仪》。"},{"text":"「不退了，留着。」到底没舍得。","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你到底没舍得退。书留在案头，你却依旧不敢认，自己其实盼着那一册册。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"门房的书"},{"id":"G-046","branch":"G","stage":4,"day":46,"shichen":"辰时","checkpoint":"雅集论碑","scene":"又一场雅集，这次你主动随二哥去了。赵不弃正与人辩一通碑的年代，你听出他引错了条，轻轻递了张浮签过去。","options":[{"text":"「这通碑，当系建中靖国年间。」低声补正。","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你补得准，满座称善。他看了你一眼，眼里是实打实的欣赏，不掺半分轻慢。","source":"宋人雅集论学，见《东京梦华录》。"},{"text":"「与我无关，我不掺和。」袖手旁观。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你袖手旁观。他自行勘误，也没怪你。可你错过了一回，光明正大站在他身侧。","source":"同上。"}],"difficulty":2,"npc":["赵不弃","二哥"],"foreshadow":"雅集"},{"id":"G-046-未","branch":"G","stage":4,"day":46,"shichen":"未时","checkpoint":"二哥护妹","scene":"归途二哥叹：「外头闲话难听，要不……算了吧？」你停步：「二哥，这是我自个儿的事。你护我，我领；替我做主，不成。」","options":[{"text":"「谢二哥，但这一回，我自己拿主意。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"二哥愣了，继而笑了：「长大了。」你第一次，把亲哥也划在了「替你做主」之外。","source":"宋女成年婚嫁可自陈意愿，见司马光《书仪》。"},{"text":"「二哥说得对，算了吧。」低头。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你低头应了。二哥是疼你，可这一退，又把自个儿交回别人手里了。","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":null},{"id":"G-046-戌","branch":"G","stage":4,"day":46,"shichen":"戌时","checkpoint":"夜话·怕与不怕","scene":"夜话，灯下你忽然说：「阿瓷，我好像不怕他，我只怕从前的自己。」阿瓷替你掖了掖被角，没说话。","options":[{"text":"「阿瓷，我好像不怕他，我只怕从前的自己。」","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"阿瓷替你掖了掖被角，没多话。这句「不怕」，比千句情话都重。","source":"李清照自立其身，见《金石录后序》。"},{"text":"「可这回，我想试试自己挑。」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"灯影里你轻轻吐出这句。试着自己挑，不是急着嫁，是你终于肯为自己往前迈一步。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"灯","flavor":true},{"id":"G-047","branch":"G","stage":4,"day":47,"shichen":"辰时","checkpoint":"旧稿重校","scene":"他带来李清照《金石录后序》稿本残页，说：「易安先生兵火失书，写『余自中年，遭此大变』——书散了，人却立住了。」你抚过那行字，久久没说话。","options":[{"text":"「书散了，人还在。这便是了。」","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你接住了这句。遭大变而不倒，是李娘子留给你最硬的一课。","source":"李清照《金石录后序》。"},{"text":"「这稿子晦气，莫与我提。」推远。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你推远了稿子。他也不勉强。可易安先生那句，到底在你心里留了印。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":"《金石录》稿本"},{"id":"G-047-未","branch":"G","stage":4,"day":47,"shichen":"未时","checkpoint":"张成余波","scene":"阿瓷忽想起：「前头张家的人，前些日子还来问过娘子近况，被我挡了。」你淡淡：「提他作甚。日子是往前过的。」","options":[{"text":"「旧账翻篇，不与他纠缠。」淡淡揭过。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你只一句便揭过。张家的余波，到这儿就算散了。你不再拿旧人，赔自己的新日子。","source":"宋代退亲之制，见《宋史·礼志》及宋人笔记。"},{"text":"「他还来问？！唤他来说清楚。」","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你动了气要唤人。阿瓷劝住：翻旧账，只会把新日子也搅浑。你终是忍了。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":null},{"id":"G-047-戌","branch":"G","stage":4,"day":47,"shichen":"戌时","checkpoint":"门房又书","scene":"朔日又至，门房的书照旧到了。这回你没退，也没立刻取，只问阿瓷：「今儿是什么帖？」阿瓷：「《礼》的婚仪卷。」你哦了声。","options":[{"text":"「取来吧，我瞧瞧宋人怎么成礼。」","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你取了书，认真翻婚仪卷。不是急着嫁，是想先把「礼」看明白，再谈别的。","source":"宋人婚前有「纳采」「问名」之礼，重循序渐进，见《书仪》。"},{"text":"「放那儿，迟些再看。」仍不取。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你仍不取。书在门房搁着，像你那点心思，明明在意，偏不肯认。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"门房的书"},{"id":"G-048","branch":"G","stage":4,"day":48,"shichen":"辰时","checkpoint":"碑林同游","scene":"休沐日，他邀你去城外碑林，二哥作陪。林里古碑森森，他指一方唐碑：「这通，我想与你同校，可好？」二哥在旁点头。","options":[{"text":"「好。校书这等事，本该两个人。」","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你们就着碑石同校半日。阳光落在字口里，也落在你肩上。这是头回，你觉着「两人」不吓人。","source":"宋人同游碑林校石刻，见《金石录后序》。"},{"text":"「我瞧瞧便走，不校了。」匆匆一巡。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你匆匆一巡便走。他也不留。你错过的，是头一回有人邀你「同」做一件事。","source":"同上。"}],"difficulty":2,"npc":["赵不弃","二哥"],"foreshadow":"碑拓"},{"id":"G-048-未","branch":"G","stage":4,"day":48,"shichen":"未时","checkpoint":"阿瓷看人","scene":"归途阿瓷悄说：「赵公子那人，待娘子是真的。方才你鞋带松了，他背过身去，等你系好才回头。」你脚步一顿。","options":[{"text":"「……这样的人，倒少见。」记在心里。","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"你把这一桩小事收进心里。尊重不是嘴上功夫，是背过身等你系鞋带的半刻。","source":"宋人重「相敬如宾」，见《书仪》。"},{"text":"「小厮都会的礼数，算得什么。」","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你不以为意。可阿瓷说的是「背过身」——那是体面人，才肯给的分寸。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":null},{"id":"G-048-戌","branch":"G","stage":4,"day":48,"shichen":"戌时","checkpoint":"自挑之念","scene":"夜里你忽然对阿瓷说：「那回是旁人给的，这回，我想自个儿挑。」阿瓷眼睛一亮：「娘子早该这么想。」你笑了，是许久没笑过的松快。","options":[{"text":"「那回是旁人给的，这回，我想自个儿挑。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你头一回，把「嫁」当成自己能挑的事。从前是命，这回，是你自己伸的手。","source":"宋代户婚之法，见《宋史·刑法志》。"},{"text":"「挑什么挑，凑合便罢。」又泄了气。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你又泄了气。可阿瓷那句「早该这么想」，像颗种子，已经落在你心里了。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":null},{"id":"G-049","branch":"G","stage":4,"day":49,"shichen":"辰时","checkpoint":"礼数相探","scene":"你寻个由头问二哥：「宋人成礼，女子也能在场拿主意么？」二哥愣：「怎么不能？六礼里女家本就有话说。」你暗暗记下了。","options":[{"text":"「那这回，每礼我都得到场。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你下了决心：纳采问名纳吉，环环都有你一句话。礼是老礼，主意是你的。","source":"宋人成礼重女家之意，见司马光《书仪》。"},{"text":"「罢了，还是家里做主省事。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你又想交回家里。二哥却摇头：「省事，是要拿你自己的日子去省的。」","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":"婚书"},{"id":"G-049-未","branch":"G","stage":4,"day":49,"shichen":"未时","checkpoint":"八字闲话","scene":"二哥半真半假：「要不，我先去替你合合八字、探探口风？」你沉吟：「行，但探归探，成不成，我说了算。」","options":[{"text":"「你去探，主意留在我这儿。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你把「探口风」交二哥，把「准不准」留自己。分寸，你拿捏得清清楚楚。","source":"宋人婚前有「问名」「纳吉」，女家可自决，见《书仪》。"},{"text":"「全交二哥办，我懒得管。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你全推给二哥。他苦笑：「探口风容易，替你点头难。这关，得你自个儿过。」","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":"婚书"},{"id":"G-049-戌","branch":"G","stage":4,"day":49,"shichen":"戌时","checkpoint":"夜话·我想自己挑","scene":"夜话，灯花又爆。你抚着那册门房送来的书，轻声说：「阿瓷，我想自己挑一回。不慌，但这一回，得是我自己点头。」她替你把灯挑亮了些。","options":[{"text":"「这一回，我要自己挑。」","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你说得不响，字字却落地有声。自己挑，是你给自己最大的尊重。","source":"李清照自立其身，见《金石录后序》。"},{"text":"「这回，我想堂堂正正站在明处。」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你想要的，不是偷偷摸摸的依靠，是明处堂堂正正的一桩好。你配得上。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"灯","flavor":true},{"id":"G-050","branch":"G","stage":4,"day":50,"shichen":"辰时","checkpoint":"朔望书满","scene":"又是朔日，门房的书已积了厚厚一摞。你把它们搬到案上，一本本抚平。阿瓷笑：「娘子这是，要开书肆了？」你也笑。","options":[{"text":"「都是他一字字批的，舍不得乱放。」","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你珍重地收好每册。这些书，是他不声不响陪你走过来的证据。","source":"同上。"},{"text":"「占地方，挑几本处理了。」","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你想处理掉。手却停在扉页那行「待娘子正」上——到底，没舍得。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"门房的书"},{"id":"G-050-未","branch":"G","stage":4,"day":50,"shichen":"未时","checkpoint":"邻女问嫁","scene":"对门新搬来的年轻娘子，怯怯来问：「姐姐，退过亲的人，真还能好好出嫁么？」你放下针线，正色看她。","options":[{"text":"「能。亲事自己点头，才算数。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你把这半年的体悟，轻轻递给她。你成了旁人的灯，也证明自己走通了这条路。","source":"宋女出嫁普遍，见《宋史》及宋人笔记。"},{"text":"「难说，看命罢。」叹口气。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你叹了口气。那娘子讪讪走了。你本可以给她底气，却把自个儿的犹疑，传了出去。","source":"同上。"}],"difficulty":1,"npc":["邻里"],"foreshadow":null},{"id":"G-050-戌","branch":"G","stage":4,"day":50,"shichen":"戌时","checkpoint":"心下定矣","scene":"夜里你铺开信笺，给二哥写：「口风可探，礼数我定。若他肯，这回，我嫁。」写罢，笔尖一顿，添了「自己挑的」四字。","options":[{"text":"「写明白：这回，是自己挑的。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你落了笔。从「不嫁了」到「自己挑」，这半年的心路，终是走通了。","source":"宋代户婚之法，见《宋史·刑法志》。"},{"text":"「罢了，先不写，再看。」揉了信笺。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你揉了信笺。心意其实定了，只是还不敢落墨——可墨不落，路就走不出去。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"婚书"},{"id":"G-051","branch":"G","stage":5,"day":51,"shichen":"辰时","checkpoint":"托兄探口","scene":"第二日你真打发二哥去探赵家口风。二哥归来，眼里有笑：「成了大半。赵家那边，早有此意，只等你开口。」","options":[{"text":"「好，既如此，礼数我来排。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你点点头。探口风是二哥跑的腿，拿主意的，从头到尾是你。","source":"同上。"},{"text":"「既是他先有意，那便依他。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你脱口「依他」。二哥提醒：「依他，可不是你自个儿挑的。莫又绕回去。」","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":"婚书"},{"id":"G-051-未","branch":"G","stage":5,"day":51,"shichen":"未时","checkpoint":"合八字","scene":"合八字那日，你破例在场。算命先生排了帖，赵不弃也看着你：「娘子若在，便一并听了。」你稳稳坐着，没躲。","options":[{"text":"「八字我也要看，合不合我认。」","correct":true,"tags":["自主","才华"],"dims":{"自主":1,"才华":1},"feedback":"你亲手接过八字帖。合与不合你都认，因为这一回，你从头到尾在场。","source":"宋婚「问名」纳八字，女家可亲参，见《书仪》。"},{"text":"「你们算罢，我回屋等。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想回避。赵不弃却留你：「娘子在场，我才踏实。」你到底坐回了原位。","source":"同上。"}],"difficulty":1,"npc":["二哥","赵不弃"],"foreshadow":"婚书"},{"id":"G-051-戌","branch":"G","stage":5,"day":51,"shichen":"戌时","checkpoint":"邻里茶会邀","scene":"你忽生一念：请邻里来家中吃茶，把闲言化作明面上的交道。阿瓷乐了：「娘子这是，要堵那些碎嘴的嘴？」你笑：「是，也不全是。」","options":[{"text":"「备茶，请左邻右舍都来。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你大大方方发帖。把闲言摆到明处，是最利落的回敬——也给你新日子，铺一层人缘。","source":"宋人邻里以茶会相交，见《东京梦华录》。"},{"text":"「还是别惹事，算了。」","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你又怯了。阿瓷惋惜：「娘子，你都走到门口了，怎又缩回去？」","source":"同上。"}],"difficulty":1,"npc":["阿瓷","邻里"],"foreshadow":"茶会"},{"id":"G-052","branch":"G","stage":5,"day":52,"shichen":"辰时","checkpoint":"茶会备物","scene":"茶会前一日，你亲自挑了茶具点心：「先前那些闲言，今日用我家嫁资里的建盏待客。」阿瓷笑你：「娘子这是亮家底呢。」","options":[{"text":"茶会前一日，你亲自挑了茶具点心：「先前那些闲言，今日用我家嫁资里的建盏待客。」阿瓷笑你：「娘子这是亮家底呢。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你用自己嫁资里的物件待客。亮出来的是底气：我退过亲，也过得挺好。","source":"宋人斗茶之风，见《东京梦华录》。"},{"text":"「随便捡几样，别太招摇。」","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你选了最不起眼的。可茶会要的就是明处坦荡，太藏，反倒显得心虚。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"茶会"},{"id":"G-052-未","branch":"G","stage":5,"day":52,"shichen":"未时","checkpoint":"闲言接住","scene":"茶会上，那爱嚼舌的妇人又来：「赵公子知情么？」你笑着递茶：「他不仅知情，今日合八字，我也在场。」满座静了静，继而称善。","options":[{"text":"「知情，且在场，礼数我自定。」落落应下。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你一句话接住闲言。明处坦荡，碎嘴便没了缝隙。这场茶会，值了。","source":"宋代户婚之法，见《宋史·刑法志》。"},{"text":"「……您吃茶。」支吾带过。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你支吾带过。那妇人得逞似的走了。闲言最怕的不是反驳，是你自己先虚了。","source":"同上。"}],"difficulty":2,"npc":["邻里"],"foreshadow":"茶会"},{"id":"G-052-戌","branch":"G","stage":5,"day":52,"shichen":"戌时","checkpoint":"门房书续","scene":"茶会散后，门房又递进书来，附笺：「闻娘子今日待客从容，甚好。书照旧，朔望不误。」你看着笺，轻轻笑了。","options":[{"text":"「他倒什么都知道。」将书与笺并排摆好。","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"你把笺和书并排。他不在场，却把你的每一步，都看在眼里、记在心里。","source":"宋人重「相知」，见《金石录后序》。"},{"text":"「他管得倒宽。」撇了撇嘴。","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你撇嘴，却还是把笺收好。嘴上硬，心里那点暖，骗不了自己。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"门房的书"},{"id":"G-053","branch":"G","stage":5,"day":53,"shichen":"辰时","checkpoint":"邻情渐暖","scene":"茶会过后，巷里风气松了。那日爱嚼舌的妇人，竟也回赠了你一包蜜饯，讪讪道：「前儿言语冲撞。」你笑着收了。","options":[{"text":"「既往不究，往后常走动。」落落受了。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你大度受了蜜饯。闲言散了，邻里反倒近了。体面待人，是最软也最硬的回敬。","source":"宋人邻里相济，见《东京梦华录》。"},{"text":"「不必了，受不起。」冷脸拒了。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你冷脸拒了。蜜饯退回去，刚缓的邻里又僵了。得理饶人，才是真的稳。","source":"同上。"}],"difficulty":1,"npc":["邻里","阿瓷"],"foreshadow":"茶会"},{"id":"G-053-未","branch":"G","stage":5,"day":53,"shichen":"未时","checkpoint":"张家主母通情","scene":"赵不弃托二哥递话：「家母性子开明，闻娘子自立持家，甚是欣赏，只盼往后和睦。」你听了，心口一块石头落了地。","options":[{"text":"「张家主母如此，是我之幸。和睦二字，我应得。」","correct":true,"tags":["情缘","名声"],"dims":{"情缘":1,"名声":1},"feedback":"你坦然应下。新张家主母通情，是你自己挑的人家，连长辈都合你意。","source":"宋人重「妇顺」亦重「舅姑慈」，见《书仪》。"},{"text":"「张家主母嘛，横竖难缠。」先存了防备。","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你先存了防备。赵不弃无奈：「我母真不凶。」你讪讪，是自己把旧影，套了新人。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":null},{"id":"G-053-戌","branch":"G","stage":5,"day":53,"shichen":"戌时","checkpoint":"夜话·两姓之好","scene":"夜话，灯下你感叹：「那回说亲，是两姓之好；这回嫁，也是两姓之好——可这回，有我自己在里头拿主意。」阿瓷点头。","options":[{"text":"「两姓之好不假，可这回，有我自己的好。」","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你把「两姓之好」翻出了新意思：好，得先合你自己的意。这才是成年人的婚。","source":"宋代户婚之法，见《宋史·刑法志》。"},{"text":"「我挑的人，连张家主母都合我心。」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你挑的，不只是夫婿，是一整个待你以礼的人家。眼光，到底没差。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"灯","flavor":true},{"id":"G-054","branch":"G","stage":5,"day":54,"shichen":"辰时","checkpoint":"下定之礼","scene":"下定时，你坚持在女家正厅行礼，亲手接了雁与礼书。赵不弃依礼揖下，你稳稳回礼——这一揖一还，都是你点过头的主意。","options":[{"text":"亲手接了雁与礼书，稳稳回礼。","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你亲手接下定礼。简的是排场，不简的是你作为女家的体面与主意。","source":"宋人下定之礼，见司马光《书仪》。"},{"text":"「让二哥代接罢，我回避。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想回避。二哥不肯：「下定是女家的脸面，你不在，这脸面谁替你撑？」","source":"同上。"}],"difficulty":2,"npc":["二哥","赵不弃"],"foreshadow":"婚书"},{"id":"G-054-未","branch":"G","stage":5,"day":54,"shichen":"未时","checkpoint":"自挑聘物","scene":"他问要何聘物，你摇头：「我嫁资自有，不稀罕绫罗。若他实心，就寻一方好碑拓来，我最欢喜。」阿瓷笑记下了。","options":[{"text":"「别的不要，要一方好拓。」","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你挑的聘物，是合心意的金石，不是堆在箱底的浮财。这礼，是你自己定的调。","source":"宋人聘物重雅意，见《东京梦华录》。"},{"text":"「随他备，我无所谓。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你说无所谓。可婚事里连聘物都不挑，这「自己挑」三字，便空了一角。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"嫁资"},{"id":"G-054-戌","branch":"G","stage":5,"day":54,"shichen":"戌时","checkpoint":"二哥斟酌","scene":"二哥斟酒，忽正色：「妹子，这回你可真想着清楚？」你举杯与他碰了：「清楚。那回是糊涂，这回，每一步我都醒着。」","options":[{"text":"「清楚。这回我醒着，自己挑的。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"二哥看你半晌，一口饮尽。他放心的，是你的清醒。","source":"宋女自立议亲，见《书仪》。"},{"text":"「二哥莫问，到时便知。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你含糊带过。二哥叹气：「你越不说清，我越怕你又犯旧病。」","source":"同上。"}],"difficulty":1,"npc":["二哥"],"foreshadow":"婚书"},{"id":"G-055","branch":"G","stage":5,"day":55,"shichen":"辰时","checkpoint":"嫁资清点","scene":"你打开嫁资箱笼，一一清点：田契、妆盒、那几方旧拓。阿瓷：「娘子这箱底，比许多人家丰厚。」你笑：「这是我退了亲，也没丢的底气。」","options":[{"text":"「这是我退了亲，也没丢的底气。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你清得明明白白。退亲时保下的嫁资，是你这回敢挑、也挑得起的本钱。","source":"嫁资为妇人之私财，见《名公书判清明集》。"},{"text":"「到时都带过去，省得麻烦。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想一并带过夫家。阿瓷提醒：「嫁资是你的私财，混进去便难分清了。」","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"嫁资"},{"id":"G-055-未","branch":"G","stage":5,"day":55,"shichen":"未时","checkpoint":"婚仪从简","scene":"他来说：「婚仪从简可好？把银钱省下，置些书与碑拓。」你点头：「正合我意。排场是给人看的，舒服是咱自个儿的。」","options":[{"text":"「从简，把钱花在咱心坎上。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你们一拍即合。简的是俗礼，实的是两个人的心意。这婚，越商量越像样。","source":"宋人婚娶有奢简之分，见《东京梦华录》。"},{"text":"「哪能太寒酸，还是排场些。」","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你想讲排场。他笑：「听你的，可我知你本不重这个。」你这才醒：是怕人闲话罢了。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":null},{"id":"G-055-戌","branch":"G","stage":5,"day":55,"shichen":"戌时","checkpoint":"阿瓷备妆","scene":"阿瓷替你理妆，忽然红了眼：「娘子这回，眉眼是松快的。」你望着铜镜里的自己：「那回镜里的人，是怕的；这回，是笑的。」","options":[{"text":"望着镜里的自己，笑得松快。","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"镜里镜外，都是你自己挑的日子。这份松快，千金不换。","source":"宋女自立之悦，见笔记。"},{"text":"「快些罢，别多话。」","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你掩了情绪。阿瓷识趣噤声。可那句「眉眼松快」，你心里是受用的。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"妆箱"},{"id":"G-056","branch":"G","stage":5,"day":56,"shichen":"辰时","checkpoint":"婚书自拟","scene":"婚书你执意自写：「不愿用铺里现成的套话。我嫁的是赵不弃，不是『某门某氏』。」他看了稿，只说：「都依娘子。」","options":[{"text":"「婚书我自写，句句落在咱俩身上。」","correct":true,"tags":["才华","自主"],"dims":{"才华":1,"自主":1},"feedback":"你写的婚书，没有套话，只有你们。笔墨是你自己的，这桩婚，也终于姓了你的意。","source":"宋人婚书自拟之风，见《书仪》。"},{"text":"「用铺子里现成的罢，省事。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想用现成。他反倒劝：「娘子既有心意，何不自己写？」你这才提笔。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":"婚书"},{"id":"G-056-未","branch":"G","stage":5,"day":56,"shichen":"未时","checkpoint":"礼数亲定","scene":"亲迎那日的每一步——何时出门、几人随行、何物压箱——你都画了单子，与二哥、他一一核对。二哥笑：「这婚，比考状元还较真。」","options":[{"text":"「每步我都到场定，才叫我的婚。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你把每步礼数都攥在手里。较真的不是排场，是你不肯再把日子，交到别人手上。","source":"宋婚六礼女家主之，见司马光《书仪》。"},{"text":"「你们定罢，我懒得细究。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想撒手。二哥笑不出了：「妹子，这『你们定』三字，可是你前头最怕的。」","source":"同上。"}],"difficulty":1,"npc":["二哥","赵不弃"],"foreshadow":"婚书"},{"id":"G-056-戌","branch":"G","stage":5,"day":56,"shichen":"戌时","checkpoint":"邻人贺礼","scene":"茶会那日受过你待客的邻里，这回都来贺，连那爱嚼舌的妇人，也奉了双喜鞋。你一一谢过，巷里一片暖融。","options":[{"text":"「多谢诸位，这回的热闹，是我的。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你接下贺礼，也接下了邻里真心的热。从闲言到贺礼，是你自己挣来的转圜。","source":"宋人婚娶邻里相贺，见《东京梦华录》。"},{"text":"「摆着罢，不必太客气。」疏淡应付。","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你疏淡应付。阿瓷悄悄拽你：「娘子，人心是暖回来的，别又关上了门。」","source":"同上。"}],"difficulty":1,"npc":["邻里","阿瓷"],"foreshadow":"茶会"},{"id":"G-057","branch":"G","stage":5,"day":57,"shichen":"辰时","checkpoint":"婚期既定","scene":"婚期定了，是个宜嫁的好日子。你提笔在册上圈了，忽然想起一年前那场错信——同样的笔，这回写的是自己的字。","options":[{"text":"「这回圈的日子，是我自己选的。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你圈下的，是亲手挑的吉日。一年之间，同一支笔，写的是两般人生。","source":"宋人嫁娶择日，女家可参，见《书仪》。"},{"text":"「随他们挑罢，我懒得看。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想交出去。二哥提醒：「日子是你自己的，挑错了也得你过。何不自己圈？」","source":"同上。"}],"difficulty":1,"npc":["二哥","赵不弃"],"foreshadow":"婚书"},{"id":"G-057-未","branch":"G","stage":5,"day":57,"shichen":"未时","checkpoint":"旧拓重温","scene":"婚期定后，你们又摊开那方《曹全碑》拓——便是初订交的那一纸。他笑：「这『不』字，你当初指尖停过的地方。」你赧然。","options":[{"text":"「原来那日，便已起了头。」","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你们对着旧拓笑。从一方拓片，到一桩婚事，物件替你们记着来路。","source":"宋人以拓片为聘介之雅，见《金石录后序》。"},{"text":"「旧物罢了，收起来。」","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你想收起旧拓。他拦了：「留着，这是咱们的开头。」你这才由它摊着。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"金石拓片"},{"id":"G-057-戌","branch":"G","stage":5,"day":57,"shichen":"戌时","checkpoint":"夜话·石上约","scene":"夜话，灯下你抚着婚书草稿，轻声：「阿瓷，成礼后，我想同他一道，把《金石录》校完。易安先生没校完的，咱们接着。」","options":[{"text":"「成礼后，我要与他同校《金石录》。」","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你把婚后日子都盘算进了金石里。嫁人不是终点，是多了个同校书的人。","source":"李清照《金石录后序》言校书之约。"},{"text":"「易安没校完的，咱们接着校。」","correct":true,"tags":["情缘","感情"],"dims":{"情缘":1},"feedback":"你接过了易安先生的笔。两个时代的女子，都在这金石里，找到了自己的安稳。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"灯","flavor":true},{"id":"G-058","branch":"G","stage":5,"day":58,"shichen":"辰时","checkpoint":"妆箱自陈","scene":"上轿前，你亲自把嫁资箱笼一一标号：「这些是我的私财，带走；那些是陪嫁心意，随我过门。」阿瓷记着，一件不乱。","options":[{"text":"「我的嫁资，我自己列单，自己带。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你列得清清楚楚。带走的不仅是财物，是你退亲时保下的、再不让人的底气。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"「都归一处，省得麻烦。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想混作一处。阿瓷劝：「单子列清，日后才不糊涂。这是你的护身符。」","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"妆箱"},{"id":"G-058-未","branch":"G","stage":5,"day":58,"shichen":"未时","checkpoint":"亲迎前夜","scene":"亲迎前夜，他遣人送来一笺：「明日简礼，唯愿娘子舒心。若怯，便缓一缓，不弃候着。」你看着笺，安心睡了。","options":[{"text":"「他连我怯都容得，这婚，嫁得。」","correct":true,"tags":["情缘","自主"],"dims":{"情缘":1,"自主":1},"feedback":"你安心睡下。一个人肯候着你的怯，比万千排场都金贵。你挑的人，没挑错。","source":"宋人亲迎之礼，见《书仪》。"},{"text":"「他是不是嫌麻烦才从简？」","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你疑心从简是敷衍。可那句「若怯便缓」，分明是把你放在了礼数前头。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":null},{"id":"G-058-戌","branch":"G","stage":5,"day":58,"shichen":"戌时","checkpoint":"阿瓷试衣","scene":"阿瓷替你试嫁衣，忽然哽咽：「那回娘子说亲，眼是红的；这回，是亮的。」你揽她：「这回，是我自己走过去的。」","options":[{"text":"自己穿好嫁衣，眉眼是亮的。","correct":true,"tags":["自主","感情"],"dims":{"自主":1},"feedback":"你揽着阿瓷。那回是被人推着走，这回，是你自己一步步，走去的亮堂。","source":"宋女自择而嫁，见笔记。"},{"text":"「莫哭，触霉头。」","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你嘴上嫌她哭。可心里清楚：这回的亮，是阿瓷替你看见的、你自个儿的喜。","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"妆箱"},{"id":"G-059","branch":"G","stage":5,"day":59,"shichen":"辰时","checkpoint":"简礼成婚","scene":"亲迎日，一切从简：不喧鼓乐，只二三亲随。你按自己画的单子行过礼，稳稳跨过门槛。二哥在旁，眼里有光。","options":[{"text":"「简礼也好，这门槛，是我自己跨的。」","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你稳稳跨过门槛。没有喧闹，只有你点过头的主意，落成了这桩自己的婚。","source":"宋人亲迎之礼，见《书仪》。"},{"text":"「太素了，怪没面子。」","correct":false,"tags":["名声"],"dims":{"名声":1},"feedback":"你嫌素。二哥笑：「面子是旁人眼，你自个儿踏实，比啥都强。」你想想，也对。","source":"同上。"}],"difficulty":2,"npc":["赵不弃","二哥"],"foreshadow":"婚书"},{"id":"G-059-未","branch":"G","stage":5,"day":59,"shichen":"未时","checkpoint":"合卺前刻","scene":"合卺前，他在廊下等你，手里捧着那方《曹全碑》拓：「娘子可愿，今夜不谈风月，先谈谈这通碑？」你忍俊，点了头。","options":[{"text":"「好，先校碑，风月慢慢来。」","correct":true,"tags":["才华","情缘"],"dims":{"才华":1,"情缘":1},"feedback":"你们就着灯校起碑来。两个成年人，把甜藏在金石里，慢慢焐热。","source":"宋人新婚亦有谈艺之风，见《金石录后序》。"},{"text":"「今夜哪有心思校碑。」","correct":false,"tags":["情缘"],"dims":{"情缘":1},"feedback":"你笑他书呆。可灯下那通碑，到底比慌张的风月，更合你此刻的心境。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":null},{"id":"G-059-戌","branch":"G","stage":5,"day":59,"shichen":"戌时","checkpoint":"金石之约","scene":"夜深，你们约定：婚后头一年，把《金石录》残稿校完，逐条补注。他写：「与吾妻同校」，你添：「易安先生在，看着呢。」","options":[{"text":"「与君同校，不负的，是这桩自己挑的婚。」","correct":true,"tags":["情缘","才华"],"dims":{"情缘":1,"才华":1},"feedback":"你们落了约。校书是虚，相守是实。这桩婚，从金石起，也往金石里，慢慢沉。","source":"李清照与赵明诚同校《金石录》，见《金石录后序》。"},{"text":"「随口说说，未必真校。」","correct":false,"tags":["自主"],"dims":{"自主":1},"feedback":"你想打退堂鼓。他笑：「娘子说的话，我可都记着呢。」你只好认了真。","source":"同上。"}],"difficulty":1,"npc":["赵不弃"],"foreshadow":"《金石录》稿本"},{"id":"G-060","branch":"G","stage":5,"day":60,"shichen":"辰时","checkpoint":"婚仪亲定","scene":"成礼翌晨，你展开婚书与嫁资单，一件件核对——这都是你亲手定的。阿瓷笑：「娘子这婚，从头到尾，没假手旁人。」你颔首。","options":[{"text":"「从头到尾，没假手旁人，这才叫我的婚。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你核得踏实。这桩婚，笔是你写的，礼是你定的，连底气都是你自己挣的。","source":"嫁资为妇人之私财，见《名公书判清明集》。"},{"text":"「成了便罢，查什么单。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想偷懒不查。阿瓷笑：「娘子前头那么较真，这会儿倒洒脱了？」你笑着，还是核了。","source":"同上。"}],"difficulty":1,"npc":["赵不弃","阿瓷"],"foreshadow":"婚书"},{"id":"G-060-未","branch":"G","stage":5,"day":60,"shichen":"未时","checkpoint":"嫁资为凭","scene":"你打开嫁资箱，对阿瓷说：「这些是退了亲也没丢的，往后是咱自己的底气。」阿瓷：「娘子这箱底，便是这回敢挑的本钱。」","options":[{"text":"「这些是退了亲也没丢的，往后是咱自己的底气。」","correct":true,"tags":["自主","名声"],"dims":{"自主":1,"名声":1},"feedback":"你抚着箱笼。底气不是夫家给的，是你退亲时保下、这回更攥紧的私财。","source":"嫁资为私产，见司马光《书仪》。"},{"text":"「过门了，这些便归大家罢。」","correct":false,"tags":["家世"],"dims":{"家世":1},"feedback":"你想交出去。阿瓷急：「嫁资是你的私财，归了大家，便再难分得清了。」","source":"同上。"}],"difficulty":1,"npc":["阿瓷"],"foreshadow":"嫁资"},{"id":"G-060-戌","branch":"G","stage":5,"day":60,"shichen":"戌时","checkpoint":"终局·石上契","scene":"合卺夜，灯如豆。你们并坐校《金石录》，他笑问：「娘子这门亲事，可还悔？」你落笔，从容答。窗外汴京静了，只余墨香与拓声。","options":[{"text":"这门亲事，嫁的是自己挑的。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你挑的人、挑的礼、挑的日子，桩桩件件都是你自个儿的。这门亲事，嫁得堂堂正正。","source":"李清照与赵明诚同校《金石录》，见《金石录后序》。"},{"text":"嫁资是你的，日子也是你的。","correct":true,"tags":["自主","情缘"],"dims":{"自主":1,"情缘":1},"feedback":"你保住的嫁资、挑定的日子，都明明白白写着「你的」。这回的安稳，谁也拿不走。","source":"同上。"}],"difficulty":2,"npc":["赵不弃"],"foreshadow":"《金石录》稿本","finale":true}];
